/**
 * ۳۶. زندگی پی — یان مارتل
 * ۷ فصل | هر فصل ۴۰ پاراگراف طولانی
 */
object Story36 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_life_of_pi",
        chapters = listOf(
            chapter1(), chapter2(), chapter3(), chapter4(),
            chapter5(), chapter6(), chapter7(),
        )
    )

    // ─────────── فصل ۱: تورنتو ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Toronto", titlePersian = "تورنتو",
        paragraphs = listOf(
            StoryParagraph("My name is Piscine Molitor Patel, but I have been known as Pi for most of my life, since the second year of my secondary school, when I decided that I would no longer endure the mockery that my given name had brought upon me, and when I took a piece of chalk and wrote my new name on the blackboard, and I have been Pi ever since, Pi Patel, a name that has served me well, a name that has carried me through more than most names could bear.", "نام من پیسین مولیتور پاتل است، اما بیشتر عمرم را با نام پای شناخته‌ام، از سال دوم دبیرستان، وقتی تصمیم گرفتم دیگر مسخره‌ای را که نام اصلی‌ام برایم آورده بود تحمل نکنم و تکه‌گچی برداشتم و نام جدیدم را روی تخته نوشتم و از آن زمان پای بوده‌ام، پای پاتل، نامی که خوب خدمتم کرده، نامی که بیشتر از آنچه بیشتر نام‌ها می‌توانند تحمل کنند مرا حمل کرده."),
            StoryParagraph("I have been told that this story will make me believe in God, that this story will make me believe in miracles, that this story will make me believe in the resilience of the human spirit, and I do not know if any of that is true, because I have lived this story, and I still do not know what to believe, and I still do not understand how I survived, and I still do not understand why I was the one who was saved, and why my mother, my father, my brother, all of them gone, all of them consumed by the sea.", "به من گفته شده این داستان باعث می‌شود به خدا باور کنم، این داستان باعث می‌شود به معجزه باور کنم، این داستان باعث می‌شود به تاب‌آوری روح انسانی باور کنم و نمی‌دانم کدام از این‌ها درست است، چون این داستان را زندگی کرده‌ام و هنوز نمی‌دانم به چه باور کنم و هنوز نمی‌فهمم چطور زنده ماندم و هنوز نمی‌فهمم چرا من کسی بودم که نجات یافت و چرا مادرم، پدرم، برادرم، همه‌شان رفتند، همه‌شان توسط دریا بلعیده شدند."),
            StoryParagraph("I am a small man now, in my forties, living in Toronto, in a country that is not my own, in a life that is not the one I imagined, and every day I wake up in a bed that is warm, and every day I eat food that is plentiful, and every day I walk through streets that are safe, and yet, every day, I remember the ocean, and every day, I remember the tiger, and every day, I remember the boy I was, the boy who survived, the boy who learned, in the middle of the Pacific Ocean, what it means to be alive.", "الان مرد کوچکی هستم، در دهه چهل زندگی، در تورنتو زندگی می‌کنم، در کشوری که مال من نیست، در زندگی‌ای که آن نیست که تصور می‌کردم و هر روز در تختی بیدار می‌شوم که گرم است و هر روز غذایی می‌خورم که فراوان است و هر روز در خیابان‌هایی قدم می‌زنم که امن‌اند و با این حال، هر روز، اقیانوس را به یاد می‌آورم و هر روز، ببر را به یاد می‌آورم و هر روز، پسری که بودم را به یاد می‌آورم، پسری که زنده ماند، پسری که در میانه اقیانوس آرام یاد گرفت زنده بودن یعنی چه."),
            StoryParagraph("I was born in Pondicherry, in the south of India, a former French colony, a small town on the coast of the Bay of Bengal, a town of colonial architecture and dusty streets and the smell of the sea, and I was raised in a zoo, my father's zoo, a zoo that was, to me, the most wonderful place on earth, a zoo that was, to me, the only home I had ever known, a zoo that was my whole world, until my whole world was taken from me.", "در پودوچری زاده شدم، در جنوب هند، مستعمره سابق فرانسوی، شهرکی کوچک در ساحل خلیج بنگال، شهرکی با معماری استعماری و خیابان‌های خاکی و بوی دریا و در باغ‌وحشی بزرگ شدم، باغ‌وحش پدرم، باغ‌وحشی که برای من شگفت‌انگیزترین جای زمین بود، باغ‌وحشی که برای من تنها خانه‌ای بود که تا به حال شناخته بودم، باغ‌وحشی که تمام جهانم بود، تا وقتی تمام جهانم از من گرفته شد."),
            StoryParagraph("My father was a zoo keeper, a man of science and reason, a man who did not believe in God, a man who believed that animals were animals and humans were humans and that the two should never be confused, and he taught me, from a very young age, that nature was not a place of harmony but a place of violence, that the animal kingdom was not a kingdom of peace but a kingdom of teeth and claws, and that the tiger in the cage was not a friend but a predator, and that the only way to be safe was to keep a proper distance.", "پدرم باغ‌وحش‌دار بود، مردی از علم و عقل، مردی که به خدا باور نداشت، مردی که باور داشت حیوانات حیوانند و انسان‌ها انسان و این دو هرگز نباید اشتباه گرفته شوند و از سن بسیار کم به من آموخت طبیعت جای هماهنگی نیست بلکه جای خشونت است، که پادشاهی حیوانات پادشاهی صلح نیست بلکه پادشاهی دندان و چنگال است و ببر در قفس دوست نیست بلکه شکارچی است و تنها راه امن بودن حفظ فاصله مناسب است."),
            StoryParagraph("I remember the day he took me to see the tigers being fed, the day he stood behind me and told me, in a voice that was calm but uncompromising, that the tiger in the cage before me was not my friend, was not my companion, was not my anything, that the tiger was a tiger, a creature of instinct and appetite, a creature that would kill me and eat me without a moment's hesitation if ever it had the chance, and I remember the way he made me look at the tiger's eyes, and the way he made me understand that what I saw there was not affection but calculation, not love but hunger.", "روزی را به یاد می‌آورم که مرا برای دیدن غذا دادن به ببرها برد، روزی که پشت سرم ایستاد و با صدایی که آرام بود اما سازش‌ناپذیر گفت ببر در قفس مقابل من دوستم نیست، همراه من نیست، هیچ چیز من نیست، که ببر یک ببر است، موجودی از غریزه و اشتها، موجودی که اگر فرصت داشت بدون یک لحظه تردید می‌کشت و می‌خورد و به یاد می‌آورم شیوه‌ای که مرا وادار کرد به چشمان ببر نگاه کنم و شیوه‌ای که مرا وادار کرد بفهمم آنچه در آن‌ها می‌بینم محبت نیست بلکه محاسبه است، نه عشق بلکه گرسنگی."),
            StoryParagraph("'Do you understand what I am telling you?' he asked, and I nodded, and I did understand, or I thought I did, and yet, even then, even as a small boy, I could not help but feel something for the tiger, something that I could not name, something that was not fear and not friendship but something in between, something that would stay with me for the rest of my life, something that would save my life on more than one occasion.", "پرسید: «می‌فهمی چه می‌گویم؟» و سر تکان دادم و می‌فهمیدم، یا فکر می‌کردم می‌فهمم و با این حال، حتی آن موقع، حتی وقتی پسر کوچکی بودم، نمی‌توانستم برای ببر چیزی حس نکنم، چیزی که نمی‌توانستم نامش را ببرم، چیزی که نه ترس بود نه دوستی بلکه چیزی در بین، چیزی که باقی عمرم با من می‌ماند، چیزی که بیش از یک بار جانم را نجات می‌داد."),
            StoryParagraph("My mother was different; my mother was a woman of faith, a woman who believed in God, a woman who believed that the universe was not merely a collection of atoms but a living thing, a thing with a soul, a thing with a purpose, and she taught me, from the same early age, that nature was sacred, that animals were sacred, that all life was sacred, and she did not see any contradiction between her faith and my father's reason, because she believed that reason was a gift from God, and that the two, properly understood, could never conflict.", "مادرم متفاوت بود؛ مادرم زنی از ایمان بود، زنی که به خدا باور داشت، زنی که باور داشت جهان تنها مجموعه‌ای از اتم‌ها نیست بلکه موجودی زنده است، موجودی با روح، موجودی با هدف و از همان سن کم به من آموخت طبیعت مقدس است، حیوانات مقدس‌اند، همه زندگی مقدس است و هیچ تناقضی بین ایمانش و عقل پدرم نمی‌دید، چون باور داشت عقل هدیه‌ای از خداست و این دو، اگر درست فهمیده شوند، هرگز نمی‌توانند تناقض داشته باشند."),
            StoryParagraph("And I, I was a child of both, a child of faith and a child of reason, a child who went to the temple with his mother and read the books of science with his father, a child who prayed to Vishnu and to Christ and to Allah, not because he was confused but because he saw no reason to choose, because he believed, as only a child can believe, that all the gods were one god, and that all the roads led to the same destination, and that the truth, wherever it was found, was the truth.", "و من، من فرزند هر دو بودم، فرزند ایمان و فرزند عقل، فرزندی که با مادرش به معبد می‌رفت و با پدرش کتاب‌های علم می‌خواند، فرزندی که به ویشنو و مسیح و الله دعا می‌کرد، نه چون گیج بود بلکه چون دلیلی برای انتخاب نمی‌دید، چون باور داشت، همانطور که فقط بچه‌ای می‌تواند باور کند، همه خدایان یک خدا هستند و همه راه‌ها به همان مقصد می‌رسند و حقیقت، هر جا که یافته شود، حقیقت است."),
            StoryParagraph("I discovered yoga when I was young, and I discovered Christianity when I was twelve, and I discovered Islam when I was fourteen, and I did not see these as separate faiths but as different aspects of the same truth, different languages for the same prayer, different names for the same God, and this belief, which would have been considered heresy by the leaders of any of these faiths, was, to me, the most natural thing in the world, the most obvious thing, the thing that needed no explanation, because I had never been told that there was only one way, and so I had never learned to think that there was.", "یوگا را در جوانی کشف کردم و مسیحیت را در دوازده‌سالگی و اسلام را در چهارده‌سالگی و این‌ها را ایمان‌های جداگانه نمی‌دیدم بلکه جنبه‌های متفاوتی از همان حقیقت، زبان‌های متفاوتی برای همان دعا، نام‌های متفاوتی برای همان خدا و این باور، که توسط رهبران هر یک از این ایمان‌ها بدعت تلقی می‌شد، برای من طبیعی‌ترین چیز دنیا بود، واضح‌ترین چیز، چیزی که نیازی به توضیح نداشت، چون هرگز به من گفته نشده بود فقط یک راه وجود دارد و بنابراین هرگز یاد نگرفته بودم فکر کنم که وجود دارد."),
            StoryParagraph("My father laughed at my religiosity, my mother worried about my confusion, the priests and the pandits and the imams argued with me, tried to convince me of the error of my ways, tried to convince me that I had to choose, that I could not be a Hindu and a Christian and a Muslim at the same time, and I listened, and I nodded, and I continued to pray as I had always prayed, because I believed, with the simple certainty of a child, that God was too big to fit into any one religion, that God was too vast to be contained by any one book, that God was everywhere and in everything and available to everyone.", "پدرم به دینداری‌ام می‌خندید، مادرم از گیجی‌ام نگران بود، کشیش‌ها و پاندیت‌ها و امامان با من بحث می‌کردند، تلاش می‌کردند اشتباه راهم را بپذیرم، تلاش می‌کردند قناعتم کنند باید انتخاب کنم، نمی‌توانم همزمان هندو و مسیحی و مسلمان باشم و من گوش دادم و سر تکان دادم و همانطور که همیشه دعا کرده بودم ادامه دادم، چون باور داشتم، با یقین ساده یک بچه، که خدا بیش از حد بزرگ است که در یک دین جا شود، خدا بیش از حد وسیع است که در یک کتاب محدود شود، خدا همه‌جا و در همه چیز است و برای همه در دسترس است."),
            StoryParagraph("The zoo was my sanctuary, my sanctuary of the mind, a place where I could walk for hours, in the heat of the day, in the shade of the trees, watching the animals, listening to their sounds, and thinking, thinking about the world, thinking about God, thinking about what it all meant, and the animals were my teachers, my first and greatest teachers, and they taught me lessons that no school could ever teach.", "باغ‌وحش پناهگاهم بود، پناهگاه ذهنم، جایی که ساعت‌ها می‌توانستم قدم بزنم، در گرمای روز، در سایه درختان، تماشای حیوانات، گوش دادن به صدایشان و فکر کردن، فکر کردن به دنیا، فکر کردن به خدا، فکر کردن به معنای همه‌اش و حیوانات معلمانم بودند، نخستین و بزرگ‌ترین معلمانم و درس‌هایی به من آموختند که هیچ مدرسه‌ای هرگز نمی‌توانست بیاموزد."),
            StoryParagraph("I learned, in that zoo, that animals are not cruel, as some believe; animals are simply themselves, and their violence, when it comes, comes not from hatred but from necessity, from hunger, from fear, from the need to survive, and I learned to respect that, to honor that, to see in the animals not savages but beings, beings with their own logic, their own dignity, their own way of being in the world.", "در آن باغ‌وحش آموختم حیوانات بی‌رحم نیستند، همانطور که بعضی باور دارند؛ حیوانات تنها خودشان هستند و خشونتشان، وقتی می‌آید، نه از نفرت بلکه از ضرورت می‌آید، از گرسنگی، از ترس، از نیاز به بقا و آموختم به آن احترام بگذارم، آن را حرمت نهم، در حیوانات نه وحشی بلکه موجوداتی ببینم، موجوداتی با منطق خودشان، کرامت خودشان، شیوه خودشان از بودن در جهان."),
            StoryParagraph("I learned, also, that humans are not as different from animals as we like to believe, that we too are driven by instinct and appetite, that we too are capable of violence when we are hungry or afraid, and that the thin veneer of civilization that we have built over our animal nature is not as thick as we think, and this lesson would be confirmed, in the most terrible way, in the middle of the Pacific Ocean, when I would see what humans are capable of, and what animals are capable of, and I would no longer be able to tell the difference.", "آموختم، همچنین، انسان‌ها آنقدر که دوست داریم باور کنیم با حیوانات متفاوت نیستند، که ما هم توسط غریزه و اشتها رانده می‌شویم، که ما هم وقتی گرسنه یا ترسیده باشیم قادر به خشونتیم و این پوسته نازک تمدنی که بر طبیعت حیوانی‌مان ساخته‌ایم آنقدر که فکر می‌کنیم ضخیم نیست و این درس به وحشتناک‌ترین شکل در میانه اقیانوس آرام تأیید می‌شد، وقتی می‌دیدم انسان‌ها قادر به چه هستند و حیوانات قادر به چه هستند و دیگر نمی‌توانستم تفاوتشان را بگویم."),
            StoryParagraph("I was happy, in those early years, in that small town, in that zoo, in that world of animals and gods and books and dreams, and I did not know, could not know, that this world was about to end, that everything I loved would be taken from me, that I would be forced to confront a reality that would shatter every belief I had ever held, and that the only thing that would keep me alive would be the very things I had been taught to fear.", "در آن سال‌های نخست، در آن شهرک کوچک، در آن باغ‌وحش، در آن جهان حیوانات و خدایان و کتاب‌ها و رؤیاها خوشحال بودم و نمی‌دانستم، نمی‌توانستم بدانم، که این جهان در شرف پایان بود، که هر چیزی که دوست می‌داشتم از من گرفته می‌شد، که مجبور می‌شدم با واقعیتی روبرو شوم که هر باوری که تا به حال داشته بودم را می‌شکست و تنها چیزی که زنده‌ام نگه می‌داشت همان چیزهایی بود که به من آموخته بودند از آن‌ها بترسم."),
            StoryParagraph("My father had a friend, a man named Mr. Kumar, a man of science and reason, a man who laughed at religion, and one day, when I was about twelve, this man took me to the zoo and told me, in a voice that was kind but firm, that God did not exist, that religion was superstition, that the universe was a mechanism of matter and energy and nothing more, and I listened, and I considered, and I did not accept.", "پدرم دوستی داشت، مردی به نام آقای کومار، مردی از علم و عقل، مردی که به دین می‌خندید و یک روز، وقتی حدوداً دوازده ساله بودم، این مرد مرا به باغ‌وحش برد و با صدایی که مهربان اما محکم بود گفت خدا وجود ندارد، دین خرافه است، جهان مکانیزمی از ماده و انرژی است و نه بیشتر و من گوش دادم و در نظر گرفتم و نپذیرفتم."),
            StoryParagraph("'I have a friend,' I told him, 'who is a baker, and he says that he has met God, and I believe him.' And Mr. Kumar laughed, and I laughed with him, and we continued to walk through the zoo, past the monkeys and the giraffes and the bears, and I continued to believe in God and he continued not to, and this, I realized, was possible, was allowed, was a kind of freedom, a freedom that I have tried to preserve ever since, in every aspect of my life, in every corner of my mind.", "به او گفتم: «دوستی دارم که نانواست و می‌گوید خدا را ملاقات کرده و من باورش می‌کنم.» و آقای کومار خندید و من با او خندیدم و در باغ‌وحش قدم زدیم، از میان میمون‌ها و زرافه‌ها و خرس‌ها و من همچنان به خدا باور کردم و او همچنان نکرد و این، دریافتم، ممکن بود، مجاز بود، نوعی آزادی بود، آزادی‌ای که از آن زمان تلاش کرده‌ام در هر جنبه از زندگی‌ام، در هر گوشه ذهنم، حفظش کنم."),
            StoryParagraph("I remember the last day, the day before we left, the day I walked through the zoo one final time, saying goodbye to each of the animals, and I remember the tiger, the Bengal tiger, the most magnificent creature I had ever seen, the creature whose eyes held something that I could not understand, something that was not merely animal but something more, something that I would understand, years later, in the middle of the ocean, when I would look into those same eyes and see, for the first time, not a predator but a companion.", "آخرین روز را به یاد می‌آورم، روزی که یک روز پیش از رفتنمان بود، روزی که یک بار آخر در باغ‌وحش قدم زدم و از هر یک از حیوانات خداحافظی کردم و ببر را به یاد می‌آورم، ببر بنگال، با شکوه‌ترین موجودی که تا حالا دیده بودم، موجودی که چشمانش چیزی داشت که نمی‌توانستم بفهمم، چیزی که تنها حیوان نبود بلکه چیزی بیشتر بود، چیزی که سال‌ها بعد، در میانه اقیانوس، می‌فهمیدم، وقتی به همان چشمان نگاه می‌کردم و برای نخستین بار نه شکارچی بلکه همسفر می‌دیدم."),
            StoryParagraph("'Goodbye,' I whispered to him, and he looked at me, and for a moment, just a moment, I felt a connection with him, a connection that I could not explain, a connection that I would one day understand, a connection that would save my life, and I did not know, could not know, that this was not a goodbye but a promise, a promise that we would meet again, a promise that we would be together in a way that neither of us could have imagined.", "زمزمه کردم: «خداحافظ.» و او نگاهم کرد و برای لحظه‌ای، فقط لحظه‌ای، با او پیوندی حس کردم، پیوندی که نمی‌توانستم توضیح دهم، پیوندی که روزی می‌فهمیدم، پیوندی که جانم را نجات می‌داد و نمی‌دانستم، نمی‌توانستم بدانم، که این خداحافظی نبود بلکه وعده‌ای بود، وعده‌ای که دوباره همدیگر را می‌دیدیم، وعده‌ای که به شیوه‌ای با هم می‌بودیم که هیچ‌کدام نمی‌توانستیم تصور کنیم."),
            StoryParagraph("We left Pondicherry in 1977, when I was sixteen, when my father decided, because of political unrest and financial difficulties, that we should emigrate to Canada, that we should sell the zoo, that we should leave the only life we had ever known, and I remember standing on the dock, looking back at the town, at the zoo, at the life that was disappearing behind me, and I remember feeling, for the first time, a sorrow that was larger than myself, a sorrow that I could not name, a sorrow that I would carry with me, like a scar, like a name, like a prayer.", "پودوچری را در ۱۹۷۷ ترک کردیم، وقتی شانزده ساله بودم، وقتی پدرم تصمیم گرفت، به‌خاطر ناآرامی‌های سیاسی و مشکلات مالی، که باید به کانادا مهاجرت کنیم، باغ‌وحش را بفروشیم، تنها زندگی‌ای که تا به حال شناخته بودیم را ترک کنیم و به یاد می‌آورم روی اسکله ایستاده بودم، به شهر نگاه می‌کردم، به باغ‌وحش، به زندگی‌ای که پشت سرم ناپدید می‌شد و به یاد می‌آورم برای نخستین بار غمی حس کردم که از خودم بزرگ‌تر بود، غمی که نمی‌توانستم نامش را ببرم، غمی که با خود حمل می‌کردم، همچون زخمی، همچون نامی، همچون دعایی."),
            StoryParagraph("We sold the animals, one by one, to zoos around the world, and we packed our belongings, and we said our goodbyes, and we boarded a Japanese cargo ship, the Tsimtsum, bound for Canada, and I did not know, could not know, that this ship would never reach its destination, that this ship would sink in the middle of the Pacific Ocean, that this ship would take my family from me and leave me alone with a tiger.", "حیوانات را یکی‌یکی به باغ‌وحش‌های سراسر جهان فروختیم و وسایلمان را بستیم و خداحافظی کردیم و سوار کشتی باری ژاپنی شدیم، سیم‌تسوم، به مقصد کانادا و نمی‌دانستم، نمی‌توانستم بدانم، که این کشتی هرگز به مقصدش نمی‌رسد، که این کشتی در میانه اقیانوس آرام غرق می‌شود، که این کشتی خانواده‌ام را از من می‌گیرد و مرا با ببری تنها می‌گذارد."),
            StoryParagraph("And so my story begins, not in Toronto, not in Canada, not in the life I now live, but on a cargo ship, in the middle of the Pacific, on a night when the sky was dark and the sea was black and the world was about to end.", "و اینگونه داستانم آغاز می‌شود، نه در تورنتو، نه در کانادا، نه در زندگی‌ای که الان دارم، بلکه در کشتی باری، در میانه اقیانوس آرام، در شبی که آسمان تاریک بود و دریا سیاه و جهان در شرف پایان یافتن بود."),
            StoryParagraph("And this is the story I must tell you, the story that I have told only once before, the story that I have carried within me for all these years, the story that has shaped me, broken me, remade me, the story that, whether I like it or not, has made me who I am.", "و این همان داستانی است که باید برایتان بگویم، داستانی که فقط یک بار قبلاً گفته‌ام، داستانی که تمام این سال‌ها در درونم حمل کرده‌ام، داستانی که شکل داده به من، شکسته مرا، از نو ساخته مرا، داستانی که خواه بخواهم خواه نخواهم، مرا آنچه هستم ساخته."),
            StoryParagraph("For I am Pi Patel, the boy who survived, the boy who sailed with a tiger, the boy who learned, in the middle of the ocean, the deepest truths about life, about death, about God, about himself, and if I tell this story, it is because I must, because the story demands to be told, because the story will not let me rest until it has been spoken.", "زیرا من پای پاتلم، پسری که زنده ماند، پسری که با ببری سفر کرد، پسری که در میانه اقیانوس، عمیق‌ترین حقایق درباره زندگی و مرگ و خدا و خودش را آموخت و اگر این داستان را می‌گویم، به‌خاطر این است که باید، چون داستان می‌خواهد گفته شود، چون داستان نمی‌گذارد بیاسایم تا وقتی گفته نشده."),
            StoryParagraph("And so, with your permission, I will begin, and I will not stop, not until the end, not until I have told you everything, not until I have told you about Richard Parker.", "و بنابراین، با اجازه شما، آغاز می‌کنم و توقف نمی‌کنم، نه تا پایان، نه تا وقتی همه چیز را گفته باشم، نه تا وقتی درباره ریچارد پارکر گفته باشم."),
            StoryParagraph("For Richard Parker is the tiger, and Richard Parker is the boy, and Richard Parker is the ocean, and Richard Parker is God, and Richard Parker is everything I have ever loved and everything I have ever feared and everything I have ever been.", "زیرا ریچارد پارکر ببر است و ریچارد پارکر پسر و ریچارد پارکر اقیانوس و ریچارد پارکر خدا و ریچارد پارکر هر چیزی است که هرگز دوست داشته‌ام و هر چیزی که هرگز ترسیده‌ام و هر چیزی که هرگز بوده‌ام."),
            StoryParagraph("And this is his story, and mine, and, if you listen, if you truly listen, it will be yours as well.", "و این داستان او است و مال من و اگر گوش دهی، اگر واقعاً گوش دهی، مال تو هم خواهد بود."),
            StoryParagraph("For the ocean is vast, and the night is long, and the tiger is always near.", "زیرا اقیانوس وسیع است و شب طولانی و ببر همیشه نزدیک است."),
            StoryParagraph("And so I begin, in a small town in the south of India, in a zoo, in a world that no longer exists, in a life that is no longer mine, in a story that will never end.", "و اینگونه آغاز می‌کنم، در شهرکی کوچک در جنوب هند، در باغ‌وحشی، در جهانی که دیگر وجود ندارد، در زندگی‌ای که دیگر مال من نیست، در داستانی که هرگز پایان نمی‌یابد."),
        )
    )
// ─────────── فصل ۲: کشتی ───────────
private fun chapter2() = StoryChapter(
    number = 2, title = "The Ship", titlePersian = "کشتی",
    paragraphs = listOf(
        StoryParagraph("The Tsimtsum was not a beautiful ship, not by any means; it was a cargo vessel, a workhorse of the sea, its hull scarred by rust and salt and the countless voyages it had made across the world's oceans, its decks cluttered with the cages and crates that held our animals and our belongings, its engines groaning with the effort of pushing its great bulk through the waves, its crew a mixture of Japanese and Indian and European sailors who had seen too much of the sea to be excited by it anymore, and I remember thinking, when I first saw it, that it looked less like a ship than like a floating warehouse, a utilitarian thing, a thing with no soul.", "سیم‌تسوم کشتی زیبایی نبود، به هیچ وجه؛ یک کشتی باری بود، اسب بارکش دریا، بدنه‌اش زخم‌خورده از زنگ و نمک و سفرهای بی‌شمارش در اقیانوس‌های جهان، عرشه‌هایش پر از قفس‌ها و جعبه‌هایی که حیوانات و وسایلمان را در خود داشت، موتورهایش از تلاش برای راندن توده بزرگش در میان امواج ناله می‌کردند، خدمه‌اش آمیزه‌ای از ملوانان ژاپنی و هندی و اروپایی بود که دریا را آنقدر دیده بودند که دیگر هیجان‌زده‌شان نکند و به یاد می‌آورم وقتی نخستین بار دیدمش فکر کردم کمتر شبیه کشتی است تا انبار شناور، چیزی کارکردی، چیزی بی‌روح."),
        StoryParagraph("We had been at sea for four days when the storm began, and I do not know what caused it, whether it was a typhoon or a squall or the simple fury of a Pacific that had decided it would tolerate us no longer, but I do know that it was the worst storm I had ever seen, and I have seen many storms since, and none of them, not one, has ever come close to the fury of that night, and I do not know if such a storm could even be described in words, or if words, when faced with such power, simply fail.", "چهار روز در دریا بودیم که طوفان آغاز شد و نمی‌دانم چه باعثش شد، اینکه تیفون بود یا توفان آنی یا خشم ساده اقیانوس آرامی که تصمیم گرفته بود دیگر تحملمان نکند، اما می‌دانم که بدترین طوفانی بود که تا حالا دیده بودم و از آن زمان طوفان‌های بسیاری دیده‌ام و هیچ‌کدام، نه حتی یکی، هرگز به خشم آن شب نزدیک نشده و نمی‌دانم آیا چنین طوفانی اصلاً با کلمات قابل توصیف است، یا اینکه کلمات، وقتی با چنین قدرتی روبرو می‌شوند، صرفاً ناتوان می‌مانند."),
        StoryParagraph("My brother Ravi and I were in our cabin, trying to sleep, listening to the ship groan and creak, listening to the wind howl, listening to the waves crash against the hull, and I remember feeling, for the first time in my life, truly afraid, afraid not of anything specific but of everything in general, afraid of the world itself, afraid of the vast, indifferent power of nature, afraid of the simple fact that we were, all of us, nothing but specks of dust on the surface of an ocean that cared nothing for our existence.", "برادرم راوی و من در کابینمان بودیم، تلاش می‌کردیم بخوابیم، به ناله و جیرجیر کشتی گوش می‌دادیم، به زوزه باد، به برخورد امواج به بدنه و به یاد می‌آورم که برای نخستین بار در زندگی‌ام، به‌راستی ترسیدم، نه از چیز مشخصی بلکه از همه چیز به‌طور کلی، از خود جهان، از قدرت وسیع و بی‌تفاوت طبیعت، از این واقعیت ساده که ما، همه‌مان، چیزی جز ذرات غبار بر سطح اقیانوسی نبودیم که به وجودمان اهمیتی نمی‌داد."),
        StoryParagraph("'Pi,' Ravi said, and his voice was unusually quiet, 'do you think we will make it?' And I did not answer, because I did not know, because I did not want to lie, because I did not want to say what I feared, and because, in that moment, in the darkness of the cabin, in the roar of the storm, I understood that the answer did not matter, that the question itself was meaningless, that what mattered was only the fact of being there, of being alive, of being together, of being, in the deepest sense, human.", "راوی گفت: «پای،» و صدایش به‌طور غیرعادی آرام بود، «فکر می‌کنی می‌رسیم؟» و پاسخ ندادم، چون نمی‌دانستم، چون نمی‌خواستم دروغ بگویم، چون نمی‌خواستم چیزی را که می‌ترسیدم بگویم و چون در آن لحظه، در تاریکی کابین، در غرش طوفان، فهمیدم پاسخ مهم نیست، خود پرسش بی‌معناست، آنچه مهم است تنها واقعیت آنجاست، زنده بودن، با هم بودن، در عمیق‌ترین معنا، انسان بودن."),
        StoryParagraph("The storm continued through the night, and at some point, I must have fallen asleep, because I woke to a crash, a crash like nothing I had ever heard, a crash that came from deep within the ship, a crash that told me, in a language that needed no translation, that the ship was breaking apart, that the ship was dying, that the ship would soon be nothing but debris on the surface of the ocean, and I understood, in that moment, that nothing would ever be the same, that the world I had known was ending, that a new world, a terrible world, was about to begin.", "طوفان تمام شب ادامه یافت و در نقطه‌ای، باید خوابیده باشم، چون با یک برخورد بیدار شدم، برخوردی مثل هیچ چیزی که تا حالا شنیده بودم، برخوردی که از عمق کشتی می‌آمد، برخوردی که به زبانی که نیازی به ترجمه نداشت به من گفت کشتی در حال تکه‌تکه شدن است، کشتی در حال مردن است، کشتی به‌زودی چیزی جز آوار بر سطح اقیانوس نمی‌شود و در آن لحظه فهمیدم هیچ چیز هرگز همان نمی‌شود، جهانی که می‌شناختم در حال پایان بود، جهانی جدید، جهانی هولناک، در شرف آغاز بود."),
        StoryParagraph("I ran to the deck, and what I saw was chaos, chaos beyond anything I had ever imagined, chaos that no words can fully convey; the sky was black, the sea was black, the rain was falling in sheets, and the ship was tilting, tilting to one side, and I could hear, in the distance, the sound of animals screaming, the sound of men shouting, the sound of water rushing in, and I did not know which way to turn, did not know where to go, did not know what to do, and I understood, in that moment, what it means to be truly helpless.", "به عرشه دویدم و آنچه دیدم آشوب بود، آشوبی فراتر از هر چیزی که تا حالا تصور کرده بودم، آشوبی که هیچ کلمه‌ای نمی‌تواند کاملاً منتقلش کند؛ آسمان سیاه بود، دریا سیاه بود، باران یکسره می‌بارید و کشتی کج می‌شد، به یک طرف کج می‌شد و در دوردست می‌توانستم صدای فریاد حیوانات را بشنوم، صدای فریاد مردان، صدای هجوم آب و نمی‌دانستم به کدام سو بروم، نمی‌دانستم کجا بروم، نمی‌دانستم چه بکنم و در آن لحظه فهمیدم واقعاً درمانده بودن یعنی چه."),
        StoryParagraph("I tried to find my parents, tried to find Ravi, tried to find anyone, but the deck was chaos, the crew was running in all directions, and no one had time for a boy who was looking for his family, no one had time for anything except the simple, desperate struggle to survive, and I understood, in that moment, that I was alone, that I had always been alone, that we are all, in the end, alone, and that the only thing we can do is to try to stay alive.", "تلاش کردم پدر و مادرم را پیدا کنم، تلاش کردم راوی را پیدا کنم، تلاش کردم هر کسی را پیدا کنم اما عرشه آشوب بود، خدمه به هر سو می‌دویدند و هیچ‌کس برای پسری که دنبال خانواده‌اش بود وقت نداشت، هیچ‌کس برای هیچ چیزی وقت نداشت جز تلاش ساده و درمانده برای بقا و در آن لحظه فهمیدم که تنهایم، همیشه تنها بوده‌ام، همه‌مان در پایان تنهاییم و تنها کاری که می‌توانیم بکنیم تلاش برای زنده ماندن است."),
        StoryParagraph("A wave came over the side, a wave that was as tall as the ship itself, and I was knocked off my feet, and I felt myself being dragged, and I grabbed at something, anything, and my hands closed around the rail, and I held on, held on with all my strength, held on while the wave passed and the ship tilted and the world spun around me, and I did not let go, I could not let go, I would not let go, because I knew, with a certainty that came from somewhere deeper than thought, that letting go meant death.", "موجی از کناره آمد، موجی به بلندی خود کشتی و از پا افتادم و خود را کشیده شده حس کردم و چیزی را چنگ زدم، هر چیزی و دستانم دور نرده بسته شد و چنگ زدم، با تمام نیرو چنگ زدم، در حالی که موج گذشت و کشتی کج شد و جهان دور سرم چرخید چنگ زدم و رها نکردم، نمی‌توانستم رها کنم، رها نمی‌کردم، چون می‌دانستم، با یقینی که از جایی عمیق‌تر از اندیشه می‌آمد، که رها کردن یعنی مرگ."),
        StoryParagraph("I heard a sound that I will never forget, a sound that has haunted my dreams for decades, a sound that told me that my family was gone; it was the sound of the ship breaking, the sound of metal tearing, the sound of water rushing in, and it came from everywhere at once, and it was accompanied by screams, human screams, and I knew, in that moment, that I was alone, that my family was gone, that the world I had known had ended, that a new world, a terrible world, was about to begin.", "صدایی شنیدم که هرگز فراموش نمی‌کنم، صدایی که دهه‌ها رؤیاهایم را تسخیر کرده، صدایی که به من گفت خانواده‌ام رفته؛ صدای شکستن کشتی بود، صدای پاره شدن فلز، صدای هجوم آب و از هر سو در آن واحد می‌آمد و با فریادها همراه بود، فریادهای انسانی و در آن لحظه دانستم که تنهایم، خانواده‌ام رفته، جهانی که می‌شناختم پایان یافته، جهانی جدید، جهانی هولناک، در شرف آغاز بود."),
        StoryParagraph("The ship sank, and I sank with it, and I do not know how I survived, do not know how I was not pulled down by the suction, do not know how I found myself, minutes or hours or days later, in a lifeboat, in the middle of the ocean, under a sky that was still black with the remnants of the storm, and I do not know why I survived, and I do not know why I was chosen, and I do not know what it means, if it means anything at all, and I do not know if I will ever know.", "کشتی غرق شد و من با آن غرق شدم و نمی‌دانم چطور زنده ماندم، نمی‌دانم چطور مکیده نشدم، نمی‌دانم چطور خود را، دقایقی یا ساعت‌ها یا روزها بعد، در قایق نجاتی یافتم، در میانه اقیانوس، زیر آسمانی که هنوز از بازمانده‌های طوفان سیاه بود و نمی‌دانم چرا زنده ماندم و نمی‌دانم چرا انتخاب شدم و نمی‌دانم چه معنایی دارد، اگر اصلاً معنایی داشته باشد و نمی‌دانم آیا هرگز خواهم دانست."),
        StoryParagraph("And I was not alone in that lifeboat, though it would be many days before I fully understood this; there was another passenger with me, another survivor of the Tsimtsum, a survivor who was not human, a survivor who was, in fact, a Bengal tiger, a tiger named Richard Parker, a tiger whose name I would learn to speak with the same reverence with which I spoke the names of the gods, a tiger who would become, in ways I still do not fully understand, the most important being in my life.", "و در آن قایق نجات تنها نبودم، هرچند روزهای بسیاری طول می‌کشید تا کاملاً این را بفهمم؛ مسافر دیگری با من بود، بازمانده دیگری از سیم‌تسوم، بازمانده‌ای که انسان نبود، بازمانده‌ای که در واقع ببر بنگال بود، ببری به نام ریچارد پارکر، ببری که نامش را می‌آموختم با همان حرمتی بگویم که نام خدایان را می‌گفتم، ببری که به شیوه‌هایی که هنوز کاملاً نمی‌فهمم، مهم‌ترین موجود زندگی‌ام می‌شد."),
        StoryParagraph("I did not see him at first, because I was too exhausted, too terrified, too overwhelmed by the enormity of what had happened; I simply lay in the bottom of the boat, shivering, weeping, praying, and I did not know, could not know, that just a few feet away from me, hidden beneath a tarpaulin, was the creature that would become the most important being in my life, the creature that would become my companion, my enemy, my teacher, my everything, the creature whose name I would one day speak with more love than I had ever spoken any name before.", "نخست او را ندیدم، چون بیش از حد خسته بودم، بیش از حد ترسیده، بیش از حد مقهور عظمت آنچه اتفاق افتاده بود؛ فقط در کف قایق دراز کشیدم، لرزان، گریان، دعاکنان و نمی‌دانستم، نمی‌توانستم بدانم، که تنها چند قدم آن‌طرف‌تر از من، زیر برزنتی پنهان، موجودی بود که مهم‌ترین موجود زندگی‌ام می‌شد، موجودی که همسفرم می‌شد، دشمنم، معلمم، همه چیز من، موجودی که نامش را روزی با عشقی بیشتر از هر نامی که تا حالا گفته بودم می‌گفتم."),
        StoryParagraph("I remember the first time I saw him, remember it as if it were yesterday, remember every detail; I had climbed onto a bench to look over the side of the boat, to see if there was any sign of rescue, any sign of land, any sign of hope, and when I turned, there he was, standing on the other bench, staring at me with yellow eyes, and I understood, in that moment, what my father had tried to teach me all those years ago, that a tiger is a tiger, that a tiger is not my friend, that a tiger would kill me if it had the chance.", "نخستین بار که دیدمش را به یاد می‌آورم، مثل دیروز به یادش می‌آورم، هر جزئیات را به یاد می‌آورم؛ روی نیمکتی بالا رفته بودم تا از کناره قایق نگاه کنم، ببینم نشانه‌ای از نجات هست، نشانه‌ای از خشکی، نشانه‌ای از امید و چون چرخیدم، آنجا بود، روی نیمکت دیگر ایستاده، با چشمان زرد نگاهم می‌کرد و در آن لحظه فهمیدم پدرم تمام آن سال‌ها تلاش کرده بود چه به من بیاموزد، که ببر یک ببر است، ببر دوست من نیست، ببر اگر فرصت داشت می‌کشت."),
        StoryParagraph("The first thing I did was to jump overboard, and I do not recommend this to anyone who finds themselves in a similar situation, because the ocean is not a friend either, and the ocean will also kill you if it has the chance; I survived only because I found a small raft, a raft that had been thrown from the ship, and I climbed onto it, and I stayed there, shivering and terrified, for the rest of that first day and that first night, and I did not know, could not know, that I would spend many more days and nights on that raft, that the raft would become my only home, that the tiger would become my only companion.", "نخستین کاری که کردم پریدن به دریا بود و این را به هیچ‌کس که در موقعیت مشابه خود را می‌بیند توصیه نمی‌کنم، چون اقیانوس هم دوست نیست و اقیانوس هم اگر فرصت داشته باشد می‌کشدت؛ تنها زنده ماندم چون کلکی کوچک یافتم، کلکی که از کشتی پرتاب شده بود و روی آن بالا رفتم و آنجا ماندم، لرزان و هراسان، برای باقی آن روز نخست و آن شب نخست و نمی‌دانستم، نمی‌توانستم بدانم، که روزها و شب‌های بسیار بیشتری را روی آن کلک می‌گذراند، که کلک تنها خانه‌ام می‌شد، که ببر تنها همسفرم می‌شد."),
        StoryParagraph("And so my first night with Richard Parker was spent on a raft, tied to the lifeboat, drifting in the middle of the ocean, under a sky of stars that were so bright, so clear, so beautiful, that I could not help but weep, weep for the beauty, weep for the horror, weep for everything I had lost and everything I was about to lose.", "و اینگونه نخستین شبم با ریچارد پارکر روی کلکی گذشت، بسته به قایق نجات، سرگردان در میانه اقیانوس، زیر آسمانی از ستارگان که چنان درخشان، چنان روشن، چنان زیبا بودند که نمی‌توانستم گریه نکنم، برای زیبایی گریه کردم، برای وحشت گریه کردم، برای هر چیزی که از دست داده بودم و هر چیزی که در شرف از دست دادنش بودم."),
        StoryParagraph("I did not sleep that night, not really, not in any way that could be called sleep; I simply lay on the raft, listening to the ocean, listening to the tiger, listening to my own heart, which was still beating, which was still alive, which was still, despite everything, still hoping, and I did not know, could not know, that this was the beginning of the most important relationship of my life, the relationship that would define me, the relationship that would teach me everything I would ever need to know.", "آن شب نخوابیدم، نه واقعاً، نه به هیچ شیوه‌ای که بتوان نامش را خواب گذاشت؛ فقط روی کلک دراز کشیدم، به اقیانوس گوش دادم، به ببر، به قلب خودم، که هنوز می‌تپید، هنوز زنده بود، هنوز، با وجود همه چیز، هنوز امید داشت و نمی‌دانستم، نمی‌توانستم بدانم، که این آغاز مهم‌ترین رابطه زندگی‌ام بود، رابطه‌ای که تعریفم می‌کرد، رابطه‌ای که هر چیزی که هرگز نیاز داشتم بدانم به من می‌آموخت."),
        StoryParagraph("And so my story truly begins, on that first night, on that small raft, with a tiger in a lifeboat and a boy on a raft and a whole world of ocean between them, and I did not know, could not know, that this was not the end but the beginning, not the tragedy but the story, not the answer but the question that would define the rest of my life.", "و اینگونه داستانم به‌راستی آغاز می‌شود، در آن شب نخست، روی آن کلک کوچک، با ببری در قایق نجات و پسری روی کلک و جهانی از اقیانوس میانشان و نمی‌دانستم، نمی‌توانستم بدانم، که این پایان نبود بلکه آغاز بود، نه تراژدی بلکه داستان، نه پاسخ بلکه پرسشی که باقی عمرم را تعریف می‌کرد."),
        StoryParagraph("For this was the moment when my life split in two, into the boy I was before and the man I would become, into the world I had lost and the world I would discover, into the faith I had been given and the faith I would have to earn.", "زیرا این همان لحظه‌ای بود که زندگی‌ام به دو نیم شد، به پسری که پیش از این بودم و مردی که می‌شدم، به جهانی که از دست داده بودم و جهانی که کشف می‌کردم، به ایمانی که به من داده شده بود و ایمانی که باید به دست می‌آوردم."),
        StoryParagraph("And on that first night, on that small raft, under that sky of stars, with a tiger just a few feet away, I began the journey that would take me to the edge of madness and back, to the edge of death and back, to the edge of God and back, and I would return from that journey not the same, not different, but something else entirely, something that had no name, something that could only be described as Pi.", "و در آن شب نخست، روی آن کلک کوچک، زیر آن آسمان ستارگان، با ببری تنها چند قدم آن‌طرف‌تر، سفری را آغاز کردم که مرا به لبه جنون و باز می‌برد، به لبه مرگ و باز، به لبه خدا و باز و از آن سفر بازمی‌گشتم نه همان، نه متفاوت، بلکه چیزی کاملاً دیگر، چیزی که نامی نداشت، چیزی که تنها می‌شد به‌عنوان پای توصیفش کرد."),
        StoryParagraph("The morning after the storm came slowly, reluctantly, as if the sun itself was afraid to look upon what had happened, as if the light itself was hesitant to illuminate the wreckage of my life, and I remember the first color I saw, the orange of the lifeboat, the orange that would become, in the days and weeks and months to come, the only color in a world of blue.", "صبح روز بعد از طوفان آهسته آمد، به‌اکراه، گویی خود خورشید می‌ترسید به آنچه اتفاق افتاده بود نگاه کند، گویی خود نور تردید داشت زندگی ویران‌شده‌ام را روشن کند و نخستین رنگی که دیدم را به یاد می‌آورم، نارنجی قایق نجات، نارنجی‌ای که در روزها و هفته‌ها و ماه‌های بعد، تنها رنگ در جهانی از آبی می‌شد."),
        StoryParagraph("I did not remember, at first, what had happened; the mind, I have learned, has a way of protecting us from truths too terrible to bear, a way of blurring the edges of memory, a way of allowing us to wake into a nightmare without fully recognizing it as such, and so I woke on that first morning with a strange sense of peace, a peace that lasted only a few seconds, until the tiger moved and I remembered everything.", "نخستین بار به یاد نمی‌آوردم چه اتفاقی افتاده بود؛ ذهن، آموخته‌ام، شیوه‌ای برای محافظت از ما در برابر حقایقی دارد که تحملشان بسیار هولناک است، شیوه‌ای برای تار کردن لبه‌های خاطره، شیوه‌ای که به ما اجازه می‌دهد بدون اینکه کاملاً آن را به‌عنوان کابوس تشخیص دهیم در کابوس بیدار شویم و بنابراین آن صبح نخست با حس عجیبی از آرامش بیدار شدم، آرامشی که فقط چند ثانیه طول کشید، تا وقتی ببر تکان خورد و من همه چیز را به یاد آوردم."),
        StoryParagraph("I looked at the lifeboat, really looked at it, for the first time, and I saw that it was well-stocked, that it had supplies that would keep me alive for weeks, perhaps for months, that it had oars, and fishing gear, and a solar still, and cans of food, and a survival manual, and it seemed, in that moment, like a miracle, like a gift, like proof that God had not abandoned me, that I was not alone, that there was still hope.", "به قایق نجات نگاه کردم، برای نخستین بار واقعاً نگاهش کردم و دیدم که به‌خوبی تجهیز شده، ذخایری داشت که هفته‌ها، شاید ماه‌ها، زنده‌ام نگه می‌داشت، پارو داشت و وسایل ماهیگیری و تقطیرکننده خورشیدی و قوطی‌های غذا و دفترچه راهنمای بقا و در آن لحظه مثل معجزه به نظر می‌رسید، مثل هدیه، مثل اثبات اینکه خدا رهایم نکرده، که تنها نیستم، که هنوز امیدی هست."),
        StoryParagraph("But the supplies were in the lifeboat, and the lifeboat was the tiger's territory, and the tiger was Richard Parker, and Richard Parker was not interested in my needs, my hunger, my thirst, my fears, and so, in those first days, I did not dare to enter the lifeboat, did not dare to claim what was mine, did not dare to confront the creature who had taken what I needed.", "اما ذخایر در قایق نجات بود و قایق نجات قلمرو ببر بود و ببر ریچارد پارکر بود و ریچارد پارکر به نیازهای من علاقه‌ای نداشت، نه به گرسنگی‌ام، نه به تشنگی‌ام، نه به ترس‌هایم و بنابراین در آن روزهای نخست، جرات نکردم به قایق نجات وارد شوم، جرات نکردم آنچه مال من بود را ادعا کنم، جرات نکردم با موجودی که آنچه نیاز داشتم را گرفته بود روبرو شوم."),
        StoryParagraph("I subsisted, in those first days, on what I could find on the raft, on a few supplies that had been thrown into it, on the small stores of food and water that had been intended for emergencies, and I rationed them carefully, and I drank sparingly, and I ate only when I had to, and I waited, and I watched, and I tried to understand what kind of creature Richard Parker was.", "در آن روزهای نخست، با آنچه می‌توانستم روی کلک پیدا کنم گذراندم، با چند ذخیره‌ای که به آن پرتاب شده بود، با اندوخته‌های کوچک غذا و آب که برای شرایط اضطراری در نظر گرفته شده بود و با دقت جیره‌بندی‌شان کردم، کم نوشیدم، فقط وقتی مجبور بودم خوردم و منتظر ماندم و تماشا کردم و تلاش کردم بفهمم ریچارد پارکر چه نوع موجودی است."),
        StoryParagraph("I studied him for days, for weeks, with the attention of a man studying his own death, and I learned things about tigers that no book could have taught me, things that my father's zoo had prepared me for but had never fully conveyed, things that only the proximity of death can reveal; I learned that a tiger is a creature of routine, that a tiger is a creature of territory, that a tiger is a creature of instinct, and that these three things, if properly understood, can be used to keep a tiger at bay.", "روزها، هفته‌ها او را مطالعه کردم، با توجه مردی که مرگ خودش را مطالعه می‌کند و چیزهایی درباره ببرها آموختم که هیچ کتابی نمی‌توانست به من بیاموزد، چیزهایی که باغ‌وحش پدرم آماده‌ام کرده بود اما هرگز کاملاً منتقل نکرده بود، چیزهایی که تنها نزدیکی مرگ می‌تواند آشکار کند؛ آموختم ببر موجودی از روال است، ببر موجودی از قلمرو، ببر موجودی از غریزه و این سه چیز، اگر درست فهمیده شوند، می‌توانند برای دور نگه داشتن ببر استفاده شوند."),
        StoryParagraph("Richard Parker had been on the lifeboat before me, and he had already marked it as his territory, and this was, in a strange way, a gift; a tiger that has marked its territory will defend it against all intruders, and I, if I was careful, if I was clever, if I was patient, could position myself not as an intruder but as a resident, not as an enemy but as a subordinate, not as prey but as a companion of sorts, and this, I understood, was the only way I would survive.", "ریچارد پارکر پیش از من در قایق نجات بود و آن را به‌عنوان قلمرو خودش علامت‌گذاری کرده بود و این، به شیوه‌ای عجیب، هدیه بود؛ ببری که قلمروش را علامت‌گذاری کرده از آن در برابر همه مهاجمان دفاع می‌کند و من، اگر مراقب باشم، اگر باهوش باشم، اگر صبور باشم، می‌توانستم خودم را نه به‌عنوان مهاجم بلکه به‌عنوان ساکن، نه به‌عنوان دشمن بلکه به‌عنوان زیردست، نه به‌عنوان طعمه بلکه به‌عنوان همراهی از نوعی جای دهم و این، می‌فهمیدم، تنها راه زنده ماندنم بود."),
        StoryParagraph("The first thing I did was to establish myself on the raft, permanently, as far from the tiger as I could be while still remaining attached to the lifeboat, and I spent days there, days of sun and salt and solitude, days in which I did nothing but watch Richard Parker, study Richard Parker, learn Richard Parker, and slowly, very slowly, I began to understand him.", "نخستین کاری که کردم این بود که خودم را به‌طور دائمی روی کلک مستقر کردم، تا آنجا که می‌توانستم از ببر دور باشم در حالی که هنوز به قایق نجات متصل بودم و روزها آنجا گذراندم، روزهایی از آفتاب و نمک و تنهایی، روزهایی که هیچ کاری نمی‌کردم جز تماشای ریچارد پارکر، مطالعه ریچارد پارکر، شناختن ریچارد پارکر و آهسته، بسیار آهسته، شروع کردم به فهمیدنش."),
        StoryParagraph("I learned that Richard Parker was not, as I had feared, constantly hungry, constantly aggressive, constantly on the verge of attacking me; he was, instead, a creature of rhythm, a creature of pattern, a creature who slept for most of the day and hunted for most of the night, and this knowledge, this understanding of his rhythms, gave me my first real advantage.", "آموختم ریچارد پارکر همانطور که ترسیده بودم همیشه گرسنه، همیشه پرخاشگر، همیشه در آستانه حمله به من نبود؛ به‌جایش، موجودی از ریتم بود، موجودی از الگو، موجودی که بیشتر روز می‌خوابید و بیشتر شب شکار می‌کرد و این دانش، این فهم ریتم‌هایش، نخستین مزیت واقعی‌ام را به من داد."),
        StoryParagraph("I learned to sleep when he slept, to be awake when he was awake, to move when he was still, to be still when he moved; I learned to anticipate his moods, to read his body, to sense his intentions, and in doing so, I learned something about myself as well: that I was not, as I had always believed, a gentle soul, a peaceful being, a child of God who loved all creatures; I was, beneath all my civilization, a creature of instinct as well, a creature who wanted, above all else, to survive.", "آموختم وقتی می‌خوابید بخوابم، وقتی بیدار بود بیدار باشم، وقتی ساکن بود حرکت کنم، وقتی حرکت می‌کرد ساکن باشم؛ آموختم حالاتش را پیش‌بینی کنم، بدنش را بخوانم، نیتش را حس کنم و در این کار، چیزی درباره خودم هم آموختم: که من همانطور که همیشه باور داشتم روحی لطیف نبودم، موجودی صلح‌آمیز، فرزندی از خدا که همه موجودات را دوست می‌دارد؛ در زیر تمام تمدنم، من هم موجودی از غریزه بودم، موجودی که بیش از هر چیز می‌خواست زنده بماند."),
        StoryParagraph("I learned to fish, because I had to eat, and I learned to catch turtles, because I had to drink, and I learned to collect rainwater, because the sky, when it rained, was my only source of fresh water; I learned to use the oars as weapons, to use the boat as shelter, to use my mind as a tool, and I learned, in the process, that survival is not a single skill but a collection of skills, not a single decision but a thousand small decisions, not a single moment but a lifetime compressed into days.", "آموختم ماهی بگیرم، چون باید می‌خوردم و آموختم لاک‌پشت بگیرم، چون باید می‌نوشیدم و آموختم آب باران جمع کنم، چون آسمان، وقتی می‌بارید، تنها منبع آب شیرینم بود؛ آموختم از پاروها به‌عنوان سلاح استفاده کنم، از قایق به‌عنوان سرپناه، از ذهنم به‌عنوان ابزار و در این راه آموختم که بقا مهارتی واحد نیست بلکه مجموعه‌ای از مهارت‌هاست، تصمیمی واحد نیست بلکه هزار تصمیم کوچک است، لحظه‌ای واحد نیست بلکه عمری است فشرده شده در روزها."),
        StoryParagraph("Richard Parker, meanwhile, watched me with his yellow eyes, and I do not know what he thought of me, do not know if he considered me prey or companion or simply another feature of his environment, but I do know that he did not attack me, not in those first weeks, not even when he was hungry, not even when I was close, and this, I came to understand, was because I had positioned myself correctly, because I had made myself useful, because I had, in a sense, become his subordinate, his servant, his provider.", "ریچارد پارکر در همین حال، با چشمان زردش تماشایم می‌کرد و نمی‌دانم درباره‌ام چه فکر می‌کرد، نمی‌دانم مرا طعمه می‌دید یا همراه یا صرفاً ویژگی دیگری از محیطش، اما می‌دانم به من حمله نکرد، نه در آن هفته‌های نخست، نه حتی وقتی گرسنه بود، نه حتی وقتی نزدیک بودم و این، به فهمم آمد، به‌خاطر آن بود که خودم را درست جای داده بودم، چون خودم را مفید کرده بودم، چون به نوعی زیردستش شده بودم، خدمتکارش، تأمین‌کننده‌اش."),
        StoryParagraph("I remember the first fish I caught, remember it as if it were yesterday, remember the feel of the line in my hand and the splash in the water and the sudden, thrilling pull that told me I had succeeded; I killed the fish with my bare hands, because I had no other way, and I wept as I did it, wept for the fish, wept for myself, wept for the world in which one creature must kill another in order to live, and then I ate the fish, raw, because I had no fire, and it was the most delicious thing I had ever tasted.", "نخستین ماهی‌ای که گرفتم را به یاد می‌آورم، مثل دیروز به یادش می‌آورم، حس رشته در دستم و صدای پاشیدن آب و کشش ناگهانی و هیجان‌انگیزی که به من گفت موفق شده‌ام؛ ماهی را با دستان خالی کشتم، چون راه دیگری نداشتم و همانطور که این کار را می‌کردم گریه کردم، برای ماهی گریه کردم، برای خودم، برای جهانی که در آن موجودی باید موجود دیگری را بکشد تا زندگی کند و بعد ماهی را خوردم، خام، چون آتش نداشتم و لذیذترین چیزی بود که تا حالا چشیده بودم."),
        StoryParagraph("I learned to make fresh water from the sea, using a solar still that I constructed from the materials on the boat, and I learned to make a shelter from the sun, using a tarpaulin that I found, and I learned to make a diary, using a pen and paper that I had with me, and I wrote in that diary every day, wrote down everything that happened, wrote down everything I felt, wrote down everything I feared and hoped and remembered, because I knew that if I did not write it down, if I did not record it, if I did not bear witness to my own survival, then it would be as if it had never happened, as if I had never been, as if the whole thing had been a dream.", "آموختم از دریا آب شیرین بسازم، با استفاده از تقطیرکننده خورشیدی که از مواد قایق ساختم و آموختم از آفتاب سرپناهی بسازم، با استفاده از برزنتی که یافتم و آموختم خاطره‌نویسی کنم، با استفاده از قلم و کاغذی که همراه داشتم و هر روز در آن دفتر نوشتم، هر چیزی که اتفاق می‌افتاد را نوشتم، هر چیزی که حس می‌کردم، هر چیزی که می‌ترسیدم و امید داشتم و به یاد می‌آوردم، چون می‌دانستم اگر یادداشتش نکنم، اگر ثبتش نکنم، اگر شهادت ندهم به بقای خودم، آنگاه گویی هرگز اتفاق نیفتاده، گویی هرگز نبوده‌ام، گویی همه‌اش رؤیایی بوده."),
        StoryParagraph("The days passed, and the nights passed, and the weeks passed, and I do not know how many, do not know how many suns I saw rise and how many stars I saw fall, do not know how many fish I caught and how many turtles I killed, do not know how many times I thought I would die and how many times I was surprised to find myself still alive; all I know is that time, in the middle of the ocean, is not the same as time on land, that hours become days and days become weeks and weeks become a kind of eternity, and that in that eternity, I learned what it means to be truly alone.", "روزها گذشتند و شب‌ها گذشتند و هفته‌ها گذشتند و نمی‌دانم چند، نمی‌دانم چند خورشید را دیدم که طلوع کند و چند ستاره را دیدم که بیفتد، نمی‌دانم چند ماهی گرفتم و چند لاک‌پشت کشتم، نمی‌دانم چند بار فکر کردم می‌میرم و چند بار شگفت‌زده شدم که هنوز زنده‌ام؛ تنها می‌دانم زمان، در میانه اقیانوس، همان زمان در خشکی نیست، که ساعت‌ها روز می‌شوند و روزها هفته و هفته‌ها نوعی ابدیت و در آن ابدیت، آموختم واقعاً تنها بودن یعنی چه."),
        StoryParagraph("And yet, even in that loneliness, even in that isolation, even in that vast emptiness of sea and sky, I was not, in the deepest sense, alone; I had Richard Parker, and Richard Parker had me, and this mutual dependence, this strange symbiosis, this impossible companionship, kept us both alive, kept us both sane, kept us both, in some way I still do not fully understand, human.", "و با این حال، حتی در آن تنهایی، حتی در آن انزوا، حتی در آن تهی‌بودن وسیع دریا و آسمان، در عمیق‌ترین معنا، تنها نبودم؛ ریچارد پارکر را داشتم و ریچارد پارکر مرا داشت و این وابستگی متقابل، این همزیستی عجیب، این همراهی ناممکن، هر دویمان را زنده نگه می‌داشت، هر دویمان را عاقل، هر دویمان را، به شیوه‌ای که هنوز کاملاً نمی‌فهمم، انسان."),
        StoryParagraph("I learned, in those long weeks, that the ocean is not silent; it is loud, constantly loud, with the sound of waves and wind and fish and birds and the creaking of the boat and the breathing of the tiger, and I learned that silence, true silence, is not something that exists in the world but something that exists only in the mind, only in the spaces between thoughts, only in the moments when we are most ourselves.", "در آن هفته‌های طولانی آموختم اقیانوس ساکت نیست؛ پرصدا است، دائماً پرصدا، با صدای امواج و باد و ماهی و پرندگان و جیرجیر قایق و نفس‌های ببر و آموختم سکوت، سکوت واقعی، چیزی نیست که در جهان وجود داشته باشد بلکه چیزی است که فقط در ذهن وجود دارد، فقط در فضاهای میان افکار، فقط در لحظه‌هایی که بیشتر خودمان هستیم."),
        StoryParagraph("I learned, also, that fear is not a constant state but a series of moments, that you cannot be afraid every second of every day, that the mind, if it were always afraid, would destroy itself, and so it learns, out of necessity, to be afraid only when fear is useful, only when danger is near, only when action is required, and to be, at all other times, something else entirely, something that might almost be called peace.", "آموختم، همچنین، ترس حالتی دائمی نیست بلکه مجموعه‌ای از لحظه‌هاست، نمی‌توانی هر ثانیه از هر روز بترسی، ذهن، اگر همیشه بترسد، خودش را نابود می‌کند و بنابراین یاد می‌گیرد، از سر ضرورت، فقط وقتی ترس مفید است بترسد، فقط وقتی خطر نزدیک است، فقط وقتی عمل لازم است و در همه زمان‌های دیگر، چیز کاملاً دیگری باشد، چیزی که تقریباً می‌توان نامش را آرامش گذاشت."),
        StoryParagraph("And in that peace, in those moments between fears, I found myself thinking about God, thinking about the God I had prayed to as a child, thinking about whether that God still existed, whether that God had ever existed, whether the storm, the sinking, the death of my family, had been part of some plan, or whether they had simply been what they appeared to be: random, indifferent, meaningless.", "و در آن آرامش، در آن لحظه‌های میان ترس‌ها، خود را در حال فکر کردن به خدا یافتم، فکر کردن به خدایی که در کودکی به او دعا کرده بودم، فکر کردن به اینکه آیا آن خدا هنوز وجود دارد، آیا آن خدا هرگز وجود داشته، آیا طوفان، غرق شدن، مرگ خانواده‌ام، بخشی از نقشه‌ای بوده، یا صرفاً همان چیزی بوده که به نظر می‌رسید: تصادفی، بی‌تفاوت، بی‌معنا."),
        StoryParagraph("I did not find an answer, not then, not on the raft, not in the middle of the ocean; I only found the question, the question that would follow me for the rest of my life, the question that I would never be able to answer, the question that I would learn, in time, to live with.", "پاسخی نیافتم، نه آن موقع، نه روی کلک، نه در میانه اقیانوس؛ فقط پرسش را یافتم، پرسشی که باقی عمرم تعقیبم می‌کرد، پرسشی که هرگز نمی‌توانستم پاسخ دهم، پرسشی که در طول زمان یاد می‌گرفتم با آن زندگی کنم."),
        StoryParagraph("And that, I have come to believe, is what faith is: not the answer, but the question; not the certainty, but the doubt; not the knowing, but the living with not knowing; not the light, but the willingness to walk in the dark.", "و این، به باورم رسیده، همان چیزی است که ایمان است: نه پاسخ، بلکه پرسش؛ نه یقین، بلکه شک؛ نه دانستن، بلکه زندگی کردن با ندانستن؛ نه نور، بلکه آمادگی راه رفتن در تاریکی."),
        StoryParagraph("And so the days passed, and the nights passed, and the weeks passed, and I lived, and I survived, and I learned, and Richard Parker lived, and Richard Parker survived, and Richard Parker learned, and we became, in that small world of boat and raft and ocean, something that neither of us had ever been before.", "و اینگونه روزها گذشتند و شب‌ها گذشتند و هفته‌ها گذشتند و من زندگی کردم و جان به‌در بردم و آموختم و ریچارد پارکر زندگی کرد و جان به‌در برد و آموخت و در آن جهان کوچک قایق و کلک و اقیانوس، چیزی شدیم که هیچ‌کدام پیش از این نبوده بودیم."),
        StoryParagraph("We became partners, partners in the strange business of staying alive, partners in the long, slow, endless work of survival, and in that partnership, in that mutual dependence, in that impossible companionship, I found something I had not expected to find: a kind of love, a kind of respect, a kind of understanding that went beyond words, beyond thought, beyond anything I had ever known.", "شریک شدیم، شرکای کار عجیب زنده ماندن، شرکای کار طولانی، آهسته و بی‌پایان بقا و در آن شراکت، در آن وابستگی متقابل، در آن همراهی ناممکن، چیزی یافتم که انتظار یافتنش را نداشتم: نوعی عشق، نوعی احترام، نوعی فهم که فراتر از کلمات می‌رفت، فراتر از اندیشه، فراتر از هر چیزی که تا حالا شناخته بودم."),
        StoryParagraph("And I understood, at last, that Richard Parker was not merely a tiger, not merely an animal, not merely a companion; Richard Parker was a mirror, a mirror in which I saw myself, a mirror in which I saw my own fear and my own hunger and my own will to live, a mirror in which I saw, for the first time, what I truly was.", "و سرانجام فهمیدم ریچارد پارکر تنها ببری نبود، تنها حیوانی، تنها همراهی؛ ریچارد پارکر آینه بود، آینه‌ای که در آن خودم را می‌دیدم، آینه‌ای که در آن ترس خودم و گرسنگی خودم و اراده خودم برای زندگی را می‌دیدم، آینه‌ای که در آن، برای نخستین بار، آنچه واقعاً بودم را می‌دیدم."),
        StoryParagraph("And what I was, I discovered, was not so different from what Richard Parker was; I was a creature of instinct and appetite and will, a creature who would do whatever was necessary to survive, a creature who would kill if he had to, a creature who was, beneath all the layers of civilization and education and faith, an animal.", "و آنچه بودم، کشف کردم، چندان با آنچه ریچارد پارکر بود متفاوت نبود؛ موجودی از غریزه و اشتها و اراده بودم، موجودی که هر کاری لازم بود برای زنده ماندن می‌کرد، موجودی که اگر مجبور بود می‌کشت، موجودی که در زیر تمام لایه‌های تمدن و تحصیلات و ایمان، حیوان بود."),
        StoryParagraph("And that, I have come to believe, is the deepest truth that the ocean taught me: not that God exists, not that God does not exist, but that we are, all of us, both divine and animal, both spirit and flesh, both the image of God and the child of the jungle, and that the only choice we have, the only freedom we possess, is the choice of which part of ourselves we will let rule.", "و این، به باورم رسیده، عمیق‌ترین حقیقتی است که اقیانوس به من آموخت: نه اینکه خدا وجود دارد، نه اینکه خدا وجود ندارد، بلکه اینکه ما، همه‌مان، هم الهی و هم حیوان هستیم، هم روح و هم جسم، هم تصویر خدا و هم فرزند جنگل و تنها انتخاب ما، تنها آزادی که داریم، انتخاب این است که کدام بخش از خودمان را بگذاریم حکومت کند."),
        StoryParagraph("And so, on that raft, in the middle of the ocean, with a tiger just a few feet away, I began to understand what it means to be human, and I began to understand what it means to be alive, and I began to understand what it means to be, in the fullest sense of the word, blessed.", "و اینگونه، روی آن کلک، در میانه اقیانوس، با ببری تنها چند قدم آن‌طرف‌تر، شروع کردم به فهمیدن انسان بودن یعنی چه و شروع کردم به فهمیدن زنده بودن یعنی چه و شروع کردم به فهمیدن، در کامل‌ترین معنای کلمه، مورد لطف بودن یعنی چه."),
        StoryParagraph("And the story continues, as all stories must, into the deeper waters, into the darker nights, into the stranger encounters, into the moments that I have not yet told you, the moments that will, in time, reveal the meaning of everything that came before.", "و داستان ادامه می‌یابد، همانطور که همه داستان‌ها باید، به آب‌های عمیق‌تر، به شب‌های تاریک‌تر، به دیدارهای عجیب‌تر، به لحظه‌هایی که هنوز برایتان نگفته‌ام، لحظه‌هایی که در طول زمان معنای هر چیزی که پیش از این آمده بود را آشکار می‌کنند."),
        StoryParagraph("For the story of the tiger and the boy is not a story about survival alone; it is a story about transformation, about death and rebirth, about the journey that each of us must take, whether we want to or not, whether we know it or not, whether we survive it or not.", "زیرا داستان ببر و پسر تنها داستانی درباره بقا نیست؛ داستانی درباره دگرگونی است، درباره مرگ و تولد دوباره، درباره سفری که هر یک از ما باید بپیماید، خواه بخواهیم خواه نخواهیم، خواه بدانیم خواه ندانیم، خواه از آن جان به‌در ببریم خواه نه."),
        StoryParagraph("And so my story continues, on the raft, in the ocean, in the tiger's world, and I do not know where it will lead, and I do not know what it will cost, and I do not know what I will find at the end, if anything at all.", "و اینگونه داستانم ادامه می‌یابد، روی کلک، در اقیانوس، در جهان ببر و نمی‌دانم به کجا می‌رسد و نمی‌دانم چه هزینه‌ای دارد و نمی‌دانم در پایان چه می‌یابم، اگر اصلاً چیزی بیابم."),
        StoryParagraph("But I know that I must continue, that I must keep going, that I must keep telling the story, because the story, once it has begun, cannot be stopped, cannot be silenced, cannot be forgotten, until it has been told to its end.", "اما می‌دانم باید ادامه دهم، باید به راه رفتن ادامه دهم، باید به تعریف داستان ادامه دهم، چون داستان، یک بار که آغاز شد، نمی‌شود متوقفش کرد، نمی‌شود ساکتش کرد، نمی‌شود فراموشش کرد، تا وقتی تا پایانش گفته نشده."),
        StoryParagraph("And so I continue, into the days and the nights and the weeks and the months that followed, into the story that has no end.", "و اینگونه ادامه می‌دهم، به روزها و شب‌ها و هفته‌ها و ماه‌های بعد، به داستانی که پایانی ندارد."),
    )
)
// ─────────── فصل ۳: روزها و شب‌های اقیانوس ───────────
private fun chapter3() = StoryChapter(
    number = 3, title = "Days and Nights on the Ocean", titlePersian = "روزها و شب‌های اقیانوس",
    paragraphs = listOf(
        StoryParagraph("The days on the ocean were long, longer than any days I have ever known, longer than the days of my childhood in Pondicherry, longer than the days of my adolescence in Toronto, longer than any days that have come since, and yet, looking back, they seem to have passed in a single breath, in a single heartbeat, in a single instant of terror and wonder and grief that contained within it the whole of my life.", "روزها بر اقیانوس طولانی بودند، طولانی‌تر از هر روزی که تا به حال شناخته‌ام، طولانی‌تر از روزهای کودکی‌ام در پودوچری، طولانی‌تر از روزهای نوجوانی‌ام در تورنتو، طولانی‌تر از هر روزی که از آن زمان آمده و با این حال، در نگاه به عقب، به نظر می‌رسد در یک نفس، در یک تپش قلب، در یک لحظه از وحشت و شگفتی و اندوه گذشته‌اند که تمام عمرم را در خود داشت."),
        StoryParagraph("I learned, in those days, that time is not a river that flows at the same speed for everyone and everywhere, but a creature that changes shape and pace according to the circumstances of those who live it; on land, time is a friend, a companion, a thing that carries you forward; on the ocean, time is an enemy, an adversary, a thing that traps you in an eternal present, in an endless now, in a moment that refuses to end.", "در آن روزها آموختم زمان رودخانه‌ای نیست که با همان سرعت برای همه و همه‌جا جاری باشد، بلکه موجودی است که شکل و سرعتش را بر اساس شرایط کسانی که زندگی‌اش می‌کنند تغییر می‌دهد؛ در خشکی، زمان دوست است، همراه، چیزی که تو را به جلو می‌برد؛ در اقیانوس، زمان دشمن است، حریف، چیزی که تو را در حالتی ابدی، در نونی بی‌پایان، در لحظه‌ای که امتناع می‌کند تمام شود زندانی می‌کند."),
        StoryParagraph("I woke, every morning, to the same view: the blue of the ocean, the blue of the sky, the orange of the lifeboat, the yellow of the tiger's eyes; I woke, every morning, to the same sounds: the lapping of the waves, the creaking of the boat, the breathing of Richard Parker; I woke, every morning, to the same reality: that I was alone, that I was lost, that I might never be found.", "هر صبح با همان منظره بیدار می‌شدم: آبی اقیانوس، آبی آسمان، نارنجی قایق نجات، زردی چشمان ببر؛ هر صبح با همان صداها بیدار می‌شدم: لپ‌لپ امواج، جیرجیر قایق، نفس‌های ریچارد پارکر؛ هر صبح با همان واقعیت بیدار می‌شدم: که تنهایم، که گمشده‌ام، که ممکن است هرگز پیدا نشوم."),
        StoryParagraph("And yet, in that repetition, in that sameness, in that endless waking to the same reality, there was a kind of comfort, a kind of peace, a kind of order that I had not expected to find; because the sameness meant that I was still alive, that I had survived another night, that I was still, somehow, in the world of the living.", "و با این حال، در آن تکرار، در آن یکسانی، در آن بیدار شدن بی‌پایان به همان واقعیت، نوعی تسلی بود، نوعی آرامش، نوعی نظم که انتظار یافتنش را نداشتم؛ چون یکسانی یعنی هنوز زنده‌ام، یعنی شب دیگری را جان به‌در برده‌ام، یعنی هنوز، به نوعی، در جهان زندگانم."),
        StoryParagraph("I kept a routine, because routine was the only thing that kept me sane; I woke at dawn, when the sky first began to lighten, and I checked the raft, and I checked the lifeboat, and I checked Richard Parker, and I checked the supplies; and then I fished, because I had to eat, and I collected water, because I had to drink, and I wrote in my diary, because I had to remember.", "روالی داشتم، چون روال تنها چیزی بود که عقلم را حفظ می‌کرد؛ در سپیده‌دم بیدار می‌شدم، وقتی آسمان نخست شروع به روشن شدن می‌کرد و کلک را بررسی می‌کردم و قایق نجات را و ریچارد پارکر را و ذخایر را؛ و بعد ماهی می‌گرفتم، چون باید می‌خوردم و آب جمع می‌کردم، چون باید می‌نوشیدم و در دفترم می‌نوشتم، چون باید به یاد می‌آوردم."),
        StoryParagraph("The fishing was not easy, not at first; I had no experience, no skill, no patience; my lines tangled, my hooks came back empty, my hands bled from the work; but I learned, as I had learned everything on the ocean, by necessity, by trial, by failure, by the simple fact that failure meant death.", "ماهیگیری آسان نبود، نه در آغاز؛ تجربه‌ای نداشتم، مهارتی، صبری؛ رشته‌هایم گره می‌خورد، قلاب‌هایم خالی برمی‌گشت، دستانم از کار خون می‌آمد؛ اما آموختم، همانطور که همه چیز روی اقیانوس را آموخته بودم، از روی ضرورت، با آزمون، با شکست، با این واقعیت ساده که شکست یعنی مرگ."),
        StoryParagraph("I learned to make lures from the materials I had; I learned to use the oars as spears, to catch the fish that came too close to the surface; I learned to use my shirt as a net, to catch the smaller fish that swam in schools; and slowly, very slowly, I became a fisherman, not a good one, but one who could keep himself alive.", "آموختم از موادی که داشتم طعمه بسازم؛ آموختم از پاروها به‌عنوان نیزه استفاده کنم، تا ماهی‌هایی که خیلی نزدیک سطح می‌آمدند را بگیرم؛ آموختم از پیراهنم به‌عنوان تور استفاده کنم، تا ماهی‌های کوچک‌تری که در دسته شنا می‌کردند را بگیرم؛ و آهسته، بسیار آهسته، ماهیگیر شدم، نه ماهیگیر خوبی، اما کسی که می‌توانست خودش را زنده نگه دارد."),
        StoryParagraph("The water was harder, much harder; I could not drink the seawater, no matter how thirsty I became, because the seawater would kill me, would dry me out from the inside, would drive me mad before it killed me; I had to find fresh water, and the fresh water was in the sky, in the rain that fell rarely, and in the turtles that swam beneath the boat.", "آب سخت‌تر بود، بسیار سخت‌تر؛ نمی‌توانستم آب دریا را بنوشم، هر چقدر هم تشنه می‌شدم، چون آب دریا می‌کشتم، از درون خشکم می‌کرد، قبل از اینکه بکشد دیوانه‌ام می‌کرد؛ باید آب شیرین پیدا می‌کردم و آب شیرین در آسمان بود، در بارانی که به‌ندرت می‌بارید و در لاک‌پشت‌هایی که زیر قایق شنا می‌کردند."),
        StoryParagraph("I learned to catch turtles, learned to grab them by their shells as they surfaced, learned to cut their throats with the knife I had, learned to drink their blood, which was warm and salty and horrible, learned to eat their flesh, which was tough and stringy and satisfying; and I wept, the first time I killed a turtle, wept for the turtle, wept for myself, wept for the world.", "آموختم لاک‌پشت بگیرم، آموختم وقتی به سطح می‌آمدند از لاکشان بگیرم، آموختم با چاقویی که داشتم گلویشان را ببرم، آموختم خونشان را بنوشم، که گرم و شور و وحشتناک بود، آموختم گوشتشان را بخورم، که سفت و رشته‌رشته و سیرکننده بود؛ و نخستین بار که لاک‌پشتی را کشتم گریه کردم، برای لاک‌پشت گریه کردم، برای خودم، برای جهان."),
        StoryParagraph("I learned to collect rainwater, learned to spread the tarpaulin when the clouds gathered, learned to wring out my clothes after a storm, learned to drink from the small pools that formed in the folds of the canvas; and I learned that water, simple water, is the most precious thing in the universe, more precious than gold, more precious than diamonds, more precious than anything I had ever valued before.", "آموختم آب باران جمع کنم، آموختم وقتی ابرها جمع می‌شدند برزنت را پهن کنم، آموختم بعد از طوفان لباس‌هایم را بچلانم، آموختم از حوضچه‌های کوچکی که در چین‌های برزنت شکل می‌گرفت بنوشم؛ و آموختم آب، آب ساده، ارزشمندترین چیز در جهان است، باارزش‌تر از طلا، باارزش‌تر از الماس، باارزش‌تر از هر چیزی که تا حالا ارزشمند دانسته بودم."),
        StoryParagraph("The nights were the hardest, harder than the days, harder than the fishing, harder than the thirst; the nights were dark, so dark that I could not see my own hands, and the nights were long, so long that I thought they would never end, and the nights were full of sounds, the sounds of the ocean, the sounds of the boat, the sounds of Richard Parker, the sounds of my own fears.", "شب‌ها سخت‌ترین بودند، سخت‌تر از روزها، سخت‌تر از ماهیگیری، سخت‌تر از تشنگی؛ شب‌ها تاریک بودند، آنقدر تاریک که نمی‌توانستم دستان خودم را ببینم و شب‌ها طولانی بودند، آنقدر طولانی که فکر می‌کردم هرگز تمام نمی‌شوند و شب‌ها پر از صداها بودند، صداهای اقیانوس، صداهای قایق، صداهای ریچارد پارکر، صداهای ترس‌های خودم."),
        StoryParagraph("I would lie on the raft, in the darkness, listening to Richard Parker breathe, listening to the waves lap against the boat, listening to my own heart beat; and I would think, in those dark hours, about everything I had lost: my mother, my father, my brother, my home, my country, my future; and I would weep, silently, so that Richard Parker would not hear, so that Richard Parker would not know that I was weak.", "روی کلک دراز می‌کشیدم، در تاریکی، به نفس‌های ریچارد پارکر گوش می‌دادم، به لپ‌لپ امواج به قایق، به تپش قلب خودم؛ و در آن ساعات تاریک به هر چیزی که از دست داده بودم فکر می‌کردم: مادرم، پدرم، برادرم، خانه‌ام، کشورم، آینده‌ام؛ و بی‌صدا گریه می‌کردم، تا ریچارد پارکر نشنود، تا ریچارد پارکر نداند ضعیفم."),
        StoryParagraph("And yet, even in the darkness, even in the loneliness, even in the grief, there was something beautiful, something sacred, something that I could not name: the stars, the stars that filled the sky, the stars that seemed to be watching me, the stars that seemed to be saying, in a language older than words, that I was not alone, that the universe knew I was there, that something, some great something, was aware of my existence.", "و با این حال، حتی در تاریکی، حتی در تنهایی، حتی در اندوه، چیزی زیبا بود، چیزی مقدس، چیزی که نمی‌توانستم نامش را ببرم: ستارگان، ستارگانی که آسمان را پر کرده بودند، ستارگانی که به نظر می‌رسید تماشایم می‌کنند، ستارگانی که به نظر می‌رسید به زبانی کهن‌تر از کلمات می‌گویند تنها نیستم، که جهان می‌داند اینجا هستم، که چیزی، چیزی بزرگ، از وجودم آگاه است."),
        StoryParagraph("I learned, in those nights, to pray again; not the way I had prayed as a child, not the way I had prayed in the temple, not the way I had prayed in the church, not the way I had prayed in the mosque; but a new way, my own way, a way that had no name and no form and no rules, a way that was simply a conversation, a way that was simply a reaching out, a way that was simply the act of speaking into the darkness and hoping, against all evidence, that someone was listening.", "در آن شب‌ها آموختم دوباره دعا کنم؛ نه به شیوه‌ای که در کودکی دعا کرده بودم، نه به شیوه‌ای که در معبد، نه در کلیسا، نه در مسجد؛ بلکه شیوه‌ای نو، شیوه خودم، شیوه‌ای که نامی نداشت و شکلی و قواعدی، شیوه‌ای که صرفاً گفتگو بود، شیوه‌ای که صرفاً دراز کردن دست بود، شیوه‌ای که صرفاً عمل سخن گفتن در تاریکی بود و امیدوار بودن، برخلاف همه شواهد، که کسی گوش می‌دهد."),
        StoryParagraph("I prayed for rescue, at first, prayed for the ship that would find me, prayed for the plane that would spot me, prayed for the land that would appear on the horizon; but as the days passed, as the weeks passed, as the horizon remained empty, I stopped praying for rescue, stopped praying for the things I wanted, and began to pray for the things I needed: the strength to go on, the courage to face another day, the will to survive.", "نخست برای نجات دعا کردم، برای کشتی‌ای که پیدایم می‌کند، برای هواپیمایی که می‌بیندم، برای خشکی‌ای که در افق ظاهر می‌شود؛ اما همانطور که روزها گذشت، همانطور که هفته‌ها گذشت، همانطور که افق خالی ماند، از دعا برای نجات دست کشیدم، از دعا برای چیزهایی که می‌خواستم، و شروع کردم به دعا برای چیزهایی که نیاز داشتم: قدرتی برای ادامه دادن، شجاعتی برای رویارویی با روز دیگر، اراده‌ای برای بقا."),
        StoryParagraph("And I learned, in that process, that prayer is not about changing the world, not about asking for favors, not about bargaining with the divine; prayer is about changing the self, about finding the strength that is already within, about connecting with something larger than the small, frightened creature that each of us is, in the end.", "و در آن فرایند آموختم دعا درباره تغییر جهان نیست، درباره درخواست لطف، درباره چانه زدن با الهی؛ دعا درباره تغییر خود است، درباره یافتن قدرتی که از قبل در درون است، درباره پیوند با چیزی بزرگ‌تر از موجود کوچک و ترسیده‌ای که هر یک از ما، در پایان، هستیم."),
        StoryParagraph("And yet, even as I prayed, even as I found strength, even as I continued to survive, I could not stop asking the question, the question that would not leave me, the question that haunted every moment of every day: why? Why had this happened to me? Why had my family died? Why was I the one who was saved? What was the point, if there was any point at all?", "و با این حال، حتی همانطور که دعا می‌کردم، حتی همانطور که قدرت می‌یافتم، حتی همانطور که به زنده ماندن ادامه می‌دادم، نمی‌توانستم از پرسیدن سؤال دست بکشم، پرسشی که ترکم نمی‌کرد، پرسشی که هر لحظه از هر روز را تسخیر می‌کرد: چرا؟ چرا این برای من اتفاق افتاد؟ چرا خانواده‌ام مردند؟ چرا من کسی بودم که نجات یافت؟ چه معنایی داشت، اگر اصلاً معنایی داشت؟"),
        StoryParagraph("I did not find an answer, not then, not on the raft, not in the middle of the ocean; I only found the question, the question that would follow me for the rest of my life, the question that I would never be able to answer, the question that I would learn, in time, to live with.", "پاسخی نیافتم، نه آن موقع، نه روی کلک، نه در میانه اقیانوس؛ فقط پرسش را یافتم، پرسشی که باقی عمرم تعقیبم می‌کرد، پرسشی که هرگز نمی‌توانستم پاسخ دهم، پرسشی که در طول زمان یاد می‌گرفتم با آن زندگی کنم."),
        StoryParagraph("And yet, in that very inability to answer, in that very acceptance of the unanswerable, I began to find a strange kind of peace; because if the question was unanswerable, then the burden of answering was lifted from me; if the question had no answer, then I did not have to find one; if the question was, in the deepest sense, a mystery, then I could simply live with the mystery, could simply accept that some things are beyond understanding, could simply be, without needing to know.", "و با این حال، در همان ناتوانی از پاسخ، در همان پذیرش پاسخ‌ناپذیری، شروع کردم به یافتن نوعی آرامش عجیب؛ چون اگر پرسش پاسخ‌ناپذیر بود، بار پاسخ دادن از دوشم برداشته می‌شد؛ اگر پرسش پاسخی نداشت، نمی‌خواست یکی پیدا کنم؛ اگر پرسش، در عمیق‌ترین معنا، رازی بود، می‌توانستم به‌سادگی با راز زندگی کنم، می‌توانستم به‌سادگی بپذیرم که بعضی چیزها فراتر از فهمند، می‌توانستم به‌سادگی باشم، بی‌آنکه نیاز داشته باشم بدانم."),
        StoryParagraph("And in that being, in that simple act of existing, I began to notice things that I had not noticed before: the beauty of the sunrise over the water, the beauty of the sunset behind the clouds, the beauty of the fish that swam beneath the boat, the beauty of the birds that flew overhead, the beauty of the stars that filled the sky, the beauty of the smallest things, the beauty of life itself.", "و در آن بودن، در آن عمل ساده وجود داشتن، شروع کردم به متوجه شدن چیزهایی که قبلاً متوجه نشده بودم: زیبایی طلوع خورشید بر آب، زیبایی غروب آن پشت ابرها، زیبایی ماهیانی که زیر قایق شنا می‌کردند، زیبایی پرندگانی که بالای سر می‌پریدند، زیبایی ستارگانی که آسمان را پر کرده بودند، زیبایی کوچک‌ترین چیزها، زیبایی خود زندگی."),
        StoryParagraph("I had never noticed these things before, not in Pondicherry, not in Toronto, not in any of the places I had lived; I had been too busy, too distracted, too caught up in the business of being human to notice the beauty that surrounded me every day; but on the ocean, with nothing to distract me, with nowhere to go, with nothing to do but survive, I began to see.", "هرگز این چیزها را قبلاً متوجه نشده بودم، نه در پودوچری، نه در تورنتو، نه در هیچ‌کدام از جاهایی که زندگی کرده بودم؛ بیش از حد مشغول بودم، بیش از حد حواسم پرت، بیش از حد گرفتار در کار انسان بودن تا زیبایی‌ای که هر روز احاطه‌ام می‌کرد را متوجه شوم؛ اما روی اقیانوس، با هیچ چیزی که حواسم را پرت کند، با هیچ جایی برای رفتن، با هیچ کاری جز بقا، شروع کردم به دیدن."),
        StoryParagraph("And I understood, at last, why the mystics, why the saints, why the seekers of every faith, have always gone into the desert, have always retreated to the mountains, have always sought out the solitude of the wilderness; because it is only in emptiness that we can be filled, only in silence that we can hear, only in solitude that we can find the company that matters most, the company of the divine, the company of the self, the company of the universe itself.", "و سرانجام فهمیدم چرا عارفان، چرا مقدسان، چرا جویندگان هر ایمانی، همیشه به بیابان رفته‌اند، همیشه به کوه‌ها پناه برده‌اند، همیشه خلوت بیابان را جسته‌اند؛ چون تنها در تهی‌بودن است که می‌توانیم پر شویم، تنها در سکوت است که می‌توانیم بشنویم، تنها در تنهایی است که می‌توانیم همراهی‌ای که بیشترین اهمیت را دارد را بیابیم، همراهی الهی، همراهی خود، همراهی خود جهان."),
        StoryParagraph("Richard Parker, meanwhile, lived his own life, a life that intersected with mine but that was not the same as mine; he slept in the lifeboat, in the shade of the tarpaulin, and he hunted at night, when the moon was high and the fish came to the surface; and he watched me, always, with those yellow eyes, eyes that held something I could not name, something that was not affection and not hatred but something in between, something that I would spend the rest of my life trying to understand.", "ریچارد پارکر در همین حال، زندگی خودش را می‌کرد، زندگی‌ای که با من تلاقی داشت اما همان مال من نبود؛ در قایق نجات می‌خوابید، در سایه برزنت و شب‌ها شکار می‌کرد، وقتی ماه بالا بود و ماهی‌ها به سطح می‌آمدند؛ و همیشه با آن چشمان زرد تماشایم می‌کرد، چشمانی که چیزی داشتند که نمی‌توانستم نامش را ببرم، چیزی که نه محبت بود نه نفرت بلکه چیزی در بین، چیزی که باقی عمرم صرف تلاش برای فهمیدنش می‌کردم."),
        StoryParagraph("I began, in those weeks, to talk to him; I do not know why, I do not know what I hoped to accomplish, I do not know if he understood a single word I said; but I talked to him, every day, about everything, about my childhood, about my parents, about my brother, about my dreams, about my fears; and he listened, or he seemed to listen, or perhaps he simply tolerated the sound of my voice.", "در آن هفته‌ها شروع کردم با او صحبت کنم؛ نمی‌دانم چرا، نمی‌دانم امید داشتم به چه برسم، نمی‌دانم آیا یک کلمه از آنچه می‌گفتم را می‌فهمید؛ اما با او صحبت کردم، هر روز، درباره همه چیز، درباره کودکی‌ام، درباره پدر و مادرم، درباره برادرم، درباره رؤیاهایم، درباره ترس‌هایم؛ و او گوش داد، یا به نظر می‌رسید گوش می‌دهد، یا شاید صرفاً صدایم را تحمل می‌کرد."),
        StoryParagraph("'Richard Parker,' I would say, 'I am going to die out here, and you are going to eat me, and no one will ever know what happened to us;' and he would look at me, and I would look at him, and in that exchange of glances, in that moment of connection, in that strange communication between boy and tiger, I would find a kind of comfort, a kind of companionship, a kind of meaning.", "می‌گفتم: «ریچارد پارکر، من اینجا می‌میرم و تو مرا می‌خوری و هیچ‌کس هرگز نمی‌فهمد چه بر سرمان آمده؛» و او نگاهم می‌کرد و من نگاهش می‌کردم و در آن تبادل نگاه، در آن لحظه پیوند، در آن ارتباط عجیب میان پسر و ببر، نوعی تسلی می‌یافتم، نوعی همراهی، نوعی معنا."),
        StoryParagraph("And I began, in those weeks, to understand Richard Parker in a way that I had never understood any animal before; I understood that he was not a monster, not a demon, not a creature of evil; he was simply a tiger, a being of instinct and appetite, a being who wanted what all beings want: to live, to eat, to sleep, to be safe; and in that understanding, in that recognition of our shared nature, I began to love him.", "و در آن هفته‌ها شروع کردم به فهمیدن ریچارد پارکر به شیوه‌ای که هرگز قبلاً هیچ حیوانی را نفهمیده بودم؛ فهمیدم او هیولا نیست، شیطان نیست، موجودی از شرارت نیست؛ او صرفاً یک ببر است، موجودی از غریزه و اشتها، موجودی که همان چیزی را می‌خواهد که همه موجودات می‌خواهند: زندگی کردن، خوردن، خوابیدن، در امان بودن؛ و در آن فهم، در آن تشخیص طبیعت مشترکمان، شروع کردم به دوست داشتنش."),
        StoryParagraph("I loved him because he was alive, because he was real, because he was there; I loved him because he was the only other living being in my world, the only witness to my survival, the only proof that I was not, in fact, alone; I loved him because loving him was the only way to stay human, the only way to hold on to the part of me that was not merely animal, the only way to remain, in the deepest sense, myself.", "او را دوست داشتم چون زنده بود، چون واقعی بود، چون آنجا بود؛ او را دوست داشتم چون تنها موجود زنده دیگر در جهانم بود، تنها شاهد بقایم، تنها اثبات اینکه در واقع، تنها نبودم؛ او را دوست داشتم چون دوست داشتنش تنها راه انسان ماندن بود، تنها راه چنگ زدن به بخشی از من که تنها حیوان نبود، تنها راه باقی ماندن، در عمیق‌ترین معنا، خودم."),
        StoryParagraph("And yet, I also feared him, feared him every moment of every day, feared him with a fear that never went away; because love and fear are not opposites, as some believe; love and fear are two sides of the same coin, two aspects of the same reality, two responses to the same mystery; and Richard Parker, in his tiger way, was the most fearful and the most beloved being I had ever known.", "و با این حال، از او هم می‌ترسیدم، هر لحظه از هر روز از او می‌ترسیدم، با ترسی که هرگز از بین نمی‌رفت؛ چون عشق و ترس متضاد نیستند، همانطور که بعضی باور دارند؛ عشق و ترس دو روی یک سکه‌اند، دو جنبه از یک واقعیت، دو پاسخ به یک راز؛ و ریچارد پارکر، به شیوه ببری‌اش، هراسناک‌ترین و دوست‌داشتنی‌ترین موجودی بود که تا به حال شناخته بودم."),
        StoryParagraph("I learned, in those weeks, to live with fear; not to overcome it, not to ignore it, not to pretend that it was not there; but to live with it, to accept it, to make it a part of my daily life, the way one accepts the sun, the rain, the wind, the cold; fear, I discovered, is not an enemy but a companion, a companion that reminds us of our mortality, a companion that keeps us alert, a companion that, in its own strange way, keeps us alive.", "در آن هفته‌ها آموختم با ترس زندگی کنم؛ نه غلبه بر آن، نه نادیده گرفتنش، نه تظاهر به اینکه آنجا نیست؛ بلکه زندگی کردن با آن، پذیرفتنش، بخشی از زندگی روزانه‌ام کردنش، همانطور که آدم خورشید را می‌پذیرد، باران، باد، سرما؛ ترس، کشف کردم، دشمن نیست بلکه همراه است، همراهی که فناپذیری‌مان را یادآوری می‌کند، همراهی که هوشیار نگه‌مان می‌دارد، همراهی که، به شیوه عجیب خودش، زنده نگهمان می‌دارد."),
        StoryParagraph("And so the days passed, and the weeks passed, and the routine held, and the fear held, and the love held, and I continued to survive, one day at a time, one hour at a time, one breath at a time, until the days and the weeks became months, until the routine became a life, until the ocean became, in the strangest way, a home.", "و اینگونه روزها گذشتند و هفته‌ها گذشتند و روال ماند و ترس ماند و عشق ماند و به زنده ماندن ادامه دادم، یک روز در یک زمان، یک ساعت در یک زمان، یک نفس در یک زمان، تا وقتی روزها و هفته‌ها ماه شدند، تا وقتی روال زندگی شد، تا وقتی اقیانوس، به عجیب‌ترین شیوه، خانه شد."),
        StoryParagraph("And I began, in that time, to understand what home truly means; not the walls, not the roof, not the furniture, not the things we accumulate; but the sense of belonging, the sense of being known, the sense of being, in the deepest sense, at peace; and I found that peace on the ocean, on the raft, in the company of a tiger, in the middle of nowhere, in a way I had never found it anywhere else.", "و در آن زمان شروع کردم به فهمیدن معنای واقعی خانه؛ نه دیوارها، نه سقف، نه مبلمان، نه چیزهایی که جمع می‌کنیم؛ بلکه حس تعلق، حس شناخته شدن، حس بودن، در عمیق‌ترین معنا، در آرامش؛ و آن آرامش را روی اقیانوس یافتم، روی کلک، در همراهی ببری، در میانه هیچ‌جا، به شیوه‌ای که هرگز جای دیگری نیافته بودم."),
        StoryParagraph("And yet, even in that peace, even in that strange home, even in that companionship, I knew, always, that this was not the end; that the ocean would not keep me forever; that the tiger would not protect me forever; that the raft would not carry me forever; that I would, one day, have to face the world again, the world of humans, the world of cities, the world of things I had once known and had almost forgotten.", "و با این حال، حتی در آن آرامش، حتی در آن خانه عجیب، حتی در آن همراهی، همیشه می‌دانستم که این پایان نیست؛ که اقیانوس برای همیشه نگهم نمی‌دارد؛ که ببر برای همیشه محافظتم نمی‌کند؛ که کلک برای همیشه حمل نمی‌کند؛ که روزی مجبور می‌شوم دوباره با جهان روبرو شوم، جهان انسان‌ها، جهان شهرها، جهان چیزهایی که زمانی می‌شناختم و تقریباً فراموش کرده بودم."),
        StoryParagraph("And in that knowledge, in that anticipation, in that fear of the future, I found a new kind of strength; not the strength to survive, which I had already found; but the strength to hope, the strength to believe that there was something waiting for me on the other side of the ocean, something worth surviving for, something worth going home for.", "و در آن دانش، در آن پیش‌بینی، در آن ترس از آینده، نوعی نو از قدرت یافتم؛ نه قدرتی برای بقا، که قبلاً یافته بودم؛ بلکه قدرتی برای امید، قدرتی برای باور به اینکه چیزی آن‌سوی اقیانوس منتظرم است، چیزی که ارزش زنده ماندن برایش را دارد، چیزی که ارزش به خانه بازگشتن برایش را دارد."),
        StoryParagraph("And so I continued, day after day, week after week, month after month, clinging to life, clinging to hope, clinging to Richard Parker; and the world continued, indifferent to my struggle, indifferent to my pain, indifferent to my survival; and the ocean stretched on, endless and eternal, from horizon to horizon, from beginning to end, from nothing to nothing.", "و اینگونه ادامه دادم، روز بعد از روز، هفته بعد از هفته، ماه بعد از ماه، چنگ زده به زندگی، چنگ زده به امید، چنگ زده به ریچارد پارکر؛ و جهان ادامه یافت، بی‌تفاوت به تقلای من، بی‌تفاوت به دردم، بی‌تفاوت به بقایم؛ و اقیانوس کشیده شد، بی‌پایان و ابدی، از افق تا افق، از آغاز تا پایان، از هیچ تا هیچ."),
        StoryParagraph("And yet, in that nothing, in that vast emptiness, in that endless expanse of blue, I found something; I found a self that I had not known, a strength that I had not suspected, a peace that I had not imagined; and I understood, at last, that the ocean had given me a gift, the greatest gift of my life: the gift of knowing who I truly was, of knowing what I truly valued, of knowing what it truly meant to be alive.", "و با این حال، در آن هیچ، در آن تهی‌بودن وسیع، در آن گستره بی‌پایان آبی، چیزی یافتم؛ خودی یافتم که نمی‌شناختم، قدرتی که گمانش را نمی‌بردم، آرامشی که تصورش را نمی‌کردم؛ و سرانجام فهمیدم اقیانوس هدیه‌ای به من داده، بزرگ‌ترین هدیه زندگی‌ام: هدیه دانستن اینکه واقعاً چه کسی بودم، دانستن اینکه واقعاً چه چیزی را ارزشمند می‌دانم، دانستن اینکه واقعاً زنده بودن یعنی چه."),
        StoryParagraph("And so the days passed, and the nights passed, and the weeks passed, and I lived, and I survived, and I learned, and Richard Parker lived, and Richard Parker survived, and Richard Parker learned, and we became, in that small world of boat and raft and ocean, something that neither of us had ever been before.", "و اینگونه روزها گذشتند و شب‌ها گذشتند و هفته‌ها گذشتند و من زندگی کردم و جان به‌در بردم و آموختم و ریچارد پارکر زندگی کرد و جان به‌در برد و آموخت و در آن جهان کوچک قایق و کلک و اقیانوس، چیزی شدیم که هیچ‌کدام پیش از این نبوده بودیم."),
        StoryParagraph("And in that becoming, in that transformation, in that strange evolution of boy and tiger, I found the answer to the question that had haunted me, the question of why I had survived; not because I deserved to, not because I was chosen, not because there was a plan; but because I was there, because I was alive, because I was willing to do what was necessary to stay that way.", "و در آن شدن، در آن دگرگونی، در آن تکامل عجیب پسر و ببر، پاسخ پرسشی که تسخیرم کرده بود را یافتم، پرسش اینکه چرا زنده ماندم؛ نه چون سزاوار بودم، نه چون انتخاب شدم، نه چون نقشه‌ای بود؛ بلکه چون آنجا بودم، چون زنده بودم، چون مایل بودم هر کاری لازم است برای ادامه‌اش انجام دهم."),
        StoryParagraph("And I understood, at last, that life is not about deserving, not about being chosen, not about following a plan; life is about being here, now, in this moment, in this body, in this world; life is about the simple act of existing, the simple act of breathing, the simple act of being; and everything else, all the questions, all the answers, all the meanings we seek, they are secondary, they are decoration, they are the ornaments we place on the temple of life.", "و سرانجام فهمیدم زندگی درباره سزاوار بودن نیست، درباره انتخاب شدن، درباره پیروی از نقشه‌ای؛ زندگی درباره اینجاست، حالا، در این لحظه، در این بدن، در این جهان؛ زندگی درباره عمل ساده وجود داشتن است، عمل ساده نفس کشیدن، عمل ساده بودن؛ و هر چیز دیگری، همه پرسش‌ها، همه پاسخ‌ها، همه معناهایی که می‌جوییم، ثانویه‌اند، تزیین‌اند، زیورهایی هستند که بر معبد زندگی می‌گذاریم."),
        StoryParagraph("And so I continue, and so the story continues, and so the ocean continues, and so the tiger continues, and so the boy continues, into the days and the nights and the weeks and the months and the years that follow, into the story that has no end.", "و اینگونه ادامه می‌دهم و اینگونه داستان ادامه می‌یابد و اینگونه اقیانوس ادامه می‌یابد و اینگونه ببر ادامه می‌یابد و اینگونه پسر ادامه می‌یابد، به روزها و شب‌ها و هفته‌ها و ماه‌ها و سال‌های بعد، به داستانی که پایانی ندارد."),
        StoryParagraph("For the story of the tiger and the boy is not a story about the past; it is a story about the present, about every present, about the present moment in which we all live, the moment that is always ending and always beginning, the moment that is, in the deepest sense, eternity.", "زیرا داستان ببر و پسر داستانی درباره گذشته نیست؛ داستانی است درباره حال، درباره هر حال، درباره لحظه حالی که همه ما در آن زندگی می‌کنیم، لحظه‌ای که همیشه تمام می‌شود و همیشه آغاز، لحظه‌ای که، در عمیق‌ترین معنا، ابدیت است."),
        StoryParagraph("And that eternity, that present moment, that simple act of being, is what I want to share with you, what I want to give you, what I want you to understand.", "و آن ابدیت، آن لحظه حال، آن عمل ساده بودن، همان چیزی است که می‌خواهم با شما قسمت کنم، همان چیزی که می‌خواهم به شما بدهم، همان چیزی که می‌خواهم بفهمید."),
        StoryParagraph("For if you understand that, if you truly understand that, then you will understand everything, then you will understand life, then you will understand death, then you will understand God.", "زیرا اگر آن را بفهمید، اگر واقعاً آن را بفهمید، آنگاه همه چیز را خواهید فهمید، آنگاه زندگی را، آنگاه مرگ را، آنگاه خدا را."),
        StoryParagraph("And so I continue, into the next chapter, into the next adventure, into the next horror, into the next miracle, into the story that continues to unfold.", "و اینگونه ادامه می‌دهم، به فصل بعد، به ماجرای بعد، به وحشت بعد، به معجزه بعد، به داستانی که همچنان باز می‌شود."),
    )
)
// ─────────── فصل ۴: ایمان در اقیانوس ───────────
private fun chapter4() = StoryChapter(
    number = 4, title = "Faith on the Ocean", titlePersian = "ایمان در اقیانوس",
    paragraphs = listOf(
        StoryParagraph("It was in the third month, or perhaps the fourth, I do not remember precisely, because time on the ocean does not remember itself, because time on the ocean is not counted but only endured, only suffered, only lived; it was in that time, in that strange, endless stretch of days and nights, that I began to experience something that I had never experienced before, something that I had only read about in the books of the mystics, something that I had only heard about in the stories of the saints.", "در ماه سوم بود، یا شاید چهارم، دقیق یادم نیست، چون زمان روی اقیانوس خودش را به یاد نمی‌آورد، چون زمان روی اقیانوس شمرده نمی‌شود بلکه فقط تحمل می‌شود، فقط رنج کشیده می‌شود، فقط زندگی می‌شود؛ در آن زمان بود، در آن کشش عجیب و بی‌پایان روزها و شب‌ها، که شروع کردم به تجربه کردن چیزی که هرگز قبلاً تجربه نکرده بودم، چیزی که فقط درباره‌اش در کتاب‌های عارفان خوانده بودم، چیزی که فقط در داستان‌های مقدسان شنیده بودم."),
        StoryParagraph("I began to feel, in that time, a presence; I cannot describe it better than that, because there are no words for it, because language was invented for the ordinary things of life, for bread and water and love and fear, and not for this, not for the presence that I felt, not for the thing that came to me on the ocean, not for the visitor that arrived in the night and stayed until dawn.", "در آن زمان شروع کردم به حس کردن حضوری؛ بهتر از آن نمی‌توانم توصیفش کنم، چون کلمه‌ای برایش نیست، چون زبان برای вещей عادی زندگی اختراع شده، برای نان و آب و عشق و ترس، و نه برای این، نه برای حضوری که حس می‌کردم، نه برای چیزی که شبانه به سراغم می‌آمد و تا سپیده می‌ماند."),
        StoryParagraph("I do not know what it was; I do not know if it was God, or Vishnu, or Christ, or Allah, or something else entirely, something older than all the gods, something deeper than all the faiths; I do not know if it was a delusion, a hallucination, a product of my starving brain; I only know that it was real, more real than the ocean, more real than the tiger, more real than myself; and that it changed me, forever.", "نمی‌دانم چه بود؛ نمی‌دانم خدا بود، یا ویشنو، یا مسیح، یا الله، یا چیزی کاملاً دیگر، چیزی کهن‌تر از همه خدایان، چیزی عمیق‌تر از همه ایمان‌ها؛ نمی‌دانم توهم بود، خیال، محصول مغز گرسنه‌ام؛ فقط می‌دانم واقعی بود، واقعی‌تر از اقیانوس، واقعی‌تر از ببر، واقعی‌تر از خودم؛ و برای همیشه تغییرم داد."),
        StoryParagraph("The presence did not speak to me, not in words, not in any language I knew; but it communicated, in a way that was deeper than words, in a way that was more direct than language, in a way that bypassed the mind and spoke directly to the heart; and what it communicated was this: that I was not alone, that I had never been alone, that I would never be alone, not even in death, not even in the void, not even in the nothingness that I feared above all else.", "حضور با من صحبت نکرد، نه با کلمات، نه به هیچ زبانی که می‌شناختم؛ اما ارتباط برقرار کرد، به شیوه‌ای که عمیق‌تر از کلمات بود، به شیوه‌ای که مستقیم‌تر از زبان، به شیوه‌ای که ذهن را دور می‌زد و مستقیم با قلب صحبت می‌کرد؛ و آنچه ارتباط داد این بود: که تنها نیستم، که هرگز تنها نبوده‌ام، که هرگز تنها نخواهم بود، نه حتی در مرگ، نه حتی در نیستی، نه حتی در هیچ‌بودنی که بیش از همه می‌ترسیدم."),
        StoryParagraph("I wept, when I felt this presence, wept as I had never wept before; not the tears of grief, not the tears of fear, not the tears of loneliness; but something else, something purer, something that came from a place in me that I had never known existed; and in those tears, in that weeping, in that release, I understood what it means to be loved, truly loved, unconditionally loved, loved by something so vast, so infinite, so eternal, that no human love could ever compare.", "گریستم، وقتی این حضور را حس کردم، گریستم همانطور که هرگز قبلاً گریه نکرده بودم؛ نه اشک اندوه، نه اشک ترس، نه اشک تنهایی؛ بلکه چیز دیگری، چیزی خالص‌تر، چیزی که از جایی در من می‌آمد که هرگز نمی‌دانستم وجود دارد؛ و در آن اشک‌ها، در آن گریه، در آن رهایی، فهمیدم دوست داشته شدن یعنی چه، به‌راستی دوست داشته شدن، بی‌قید و شرط دوست داشته شدن، دوست داشته شدن توسط چیزی چنان وسیع، چنان بی‌نهایت، چنان ابدی، که هیچ عشق انسانی هرگز نمی‌توانست با آن مقایسه شود."),
        StoryParagraph("I began to see, in that time, the world differently; not as a place of suffering, not as a place of cruelty, not as a place of chance and accident; but as a place of meaning, a place of purpose, a place where everything, every wave, every star, every breath, was part of something larger, something sacred, something divine.", "در آن زمان شروع کردم به دیدن جهان به شیوه‌ای متفاوت؛ نه به‌عنوان جای رنج، نه به‌عنوان جای بی‌رحمی، نه به‌عنوان جای تصادف و اتفاق؛ بلکه به‌عنوان جای معنا، جای هدف، جایی که همه چیز، هر موج، هر ستاره، هر نفس، بخشی از چیزی بزرگ‌تر بود، چیزی مقدس، چیزی الهی."),
        StoryParagraph("And I began to understand, at last, why the sages and the saints and the seekers of every faith have always spoken of the divine in paradoxes, in contradictions, in impossibilities; because the divine is not a thing that can be contained in language, not a thing that can be captured in concepts, not a thing that can be understood by the mind; the divine is a mystery, and mystery, by its very nature, resists explanation.", "و سرانجام شروع کردم به فهمیدن چرا فرزانگان و مقدسان و جویندگان هر ایمانی همیشه از الهی با پارادوکس‌ها حرف زده‌اند، با تناقض‌ها، با ناممکن‌ها؛ چون الهی چیزی نیست که در زبان جا شود، چیزی نیست که در مفاهیم اسیر شود، چیزی نیست که با ذهن فهمیده شود؛ الهی راز است و راز، به حکم ماهیتش، در برابر توضیح مقاومت می‌کند."),
        StoryParagraph("And I began to understand, also, why the mystics have always spoken of the dark night of the soul, of the stripping away of all consolation, of the loss of every comfort; because it is only when everything is taken from us, when every support is removed, when every illusion is shattered, that we can begin to see what is truly there, what was always there, what we could not see before because we were too busy, too distracted, too full of ourselves.", "و شروع کردم به فهمیدن، همچنین، چرا عارفان همیشه از شب تاریک روح حرف زده‌اند، از کنار زدن همه تسلی‌ها، از از دست دادن هر آسودگی؛ چون تنها زمانی که همه چیز از ما گرفته می‌شود، وقتی هر پشتیبانی برداشته می‌شود، وقتی هر توهمی می‌شکند، می‌توانیم شروع کنیم به دیدن آنچه واقعاً آنجاست، آنچه همیشه آنجا بود، آنچه قبلاً نمی‌توانستیم ببینیم چون بیش از حد مشغول بودیم، بیش از حد حواسمان پرت، بیش از حد پر از خودمان."),
        StoryParagraph("And I began to understand, at last, why I had survived; not because I deserved to, not because I was chosen, not because there was a plan; but because I was there, because I was alive, because I was willing to do what was necessary to stay that way; and in that understanding, in that acceptance, in that peace, I found a kind of freedom that I had never known before.", "و سرانجام شروع کردم به فهمیدن چرا زنده ماندم؛ نه چون سزاوار بودم، نه چون انتخاب شدم، نه چون نقشه‌ای بود؛ بلکه چون آنجا بودم، چون زنده بودم، چون مایل بودم هر کاری لازم است برای ادامه‌اش انجام دهم؛ و در آن فهم، در آن پذیرش، در آن آرامش، نوعی آزادی یافتم که هرگز قبلاً نشناخته بودم."),
        StoryParagraph("Richard Parker, in that time, became something more than a tiger; he became a symbol, a messenger, a sign; not because he understood what was happening to me, not because he shared my experience, not because he cared; but because he was there, because he was the other, because in his presence I could see myself, could see my own fear and my own love, could see the truth that I could not see alone.", "ریچارد پارکر در آن زمان چیزی بیشتر از ببر شد؛ نماد شد، پیام‌آور، نشانه؛ نه چون می‌فهمید چه بر سرم می‌آید، نه چون تجربه‌ام را قسمت می‌کرد، نه چون اهمیت می‌داد؛ بلکه چون آنجا بود، چون دیگری بود، چون در حضورش می‌توانستم خودم را ببینم، ترس و عشقم را ببینم، حقیقتی که تنهایی نمی‌دیدم ببینم."),
        StoryParagraph("I began, in those weeks, to speak to the presence, as I spoke to Richard Parker; I did not know what to call it, did not know how to address it, did not know what form to give it; so I simply spoke, simply poured out my heart, simply said everything I had never said before, everything I had been too afraid to say, everything I had been too proud to admit.", "در آن هفته‌ها شروع کردم با حضور صحبت کنم، همانطور که با ریچارد پارکر صحبت می‌کردم؛ نمی‌دانستم چه صدایش کنم، نمی‌دانستم چطور خطابش کنم، نمی‌دانستم چه شکلی به آن بدهم؛ بنابراین فقط صحبت کردم، فقط دل خودم را بیرون ریختم، فقط هر چیزی که قبلاً نگفته بودم گفتم، هر چیزی که بیش از حد ترسیده بودم بگویم، هر چیزی که بیش از حد مغرور بودم اعتراف کنم."),
        StoryParagraph("I told the presence about my mother, about her faith, about her love, about the way she had taught me that God was everywhere, in everything, in everyone; I told the presence about my father, about his reason, about his doubt, about the way he had taught me to question everything, to accept nothing without evidence; I told the presence about my brother, about his laughter, about his teasing, about the way he had made me feel small and loved at the same time.", "برای حضور از مادرم گفتم، از ایمانش، از عشقش، از شیوه‌ای که به من آموخته بود خدا همه‌جا است، در همه چیز، در همه کس؛ از پدرم گفتم، از عقلش، از شکش، از شیوه‌ای که به من آموخته بود همه چیز را زیر سؤال ببرم، هیچ چیز را بدون دلیل نپذیرم؛ از برادرم گفتم، از خنده‌اش، از دست‌انداختنش، از شیوه‌ای که همزمان کوچک و دوست‌داشته‌شده حسشم می‌کرد."),
        StoryParagraph("And the presence listened, or seemed to listen, or perhaps simply held me, simply surrounded me, simply gave me the space to speak, the space to weep, the space to be; and in that space, in that silence, in that waiting, I began to heal, began to forgive, began to accept.", "و حضور گوش داد، یا به نظر می‌رسید گوش می‌دهد، یا شاید صرفاً مرا نگه داشت، صرفاً احاطه‌ام کرد، صرفاً فضایی داد تا صحبت کنم، فضایی برای گریه کردن، فضایی برای بودن؛ و در آن فضا، در آن سکوت، در آن انتظار، شروع کردم به التیام یافتن، شروع کردم به بخشیدن، شروع کردم به پذیرش."),
        StoryParagraph("I began to understand, in those days, that faith is not about certainty, not about answers, not about knowing; faith is about trust, about surrender, about the willingness to walk in the dark without needing to know where the path leads; faith is about opening the heart to something larger than the self, and letting that something carry you, guide you, hold you.", "در آن روزها شروع کردم به فهمیدن که ایمان درباره یقین نیست، درباره پاسخ‌ها، درباره دانستن؛ ایمان درباره اعتماد است، درباره تسلیم، درباره آمادگی راه رفتن در تاریکی بی‌آنکه نیاز به دانستن داشته باشی راه کجا می‌رود؛ ایمان درباره باز کردن قلب به روی چیزی بزرگ‌تر از خود است و گذاشتن آن چیز که تو را حمل کند، راهنمایی کند، نگهت دارد."),
        StoryParagraph("And I began to understand, also, that doubt is not the enemy of faith, as some believe; doubt is the companion of faith, the partner of faith, the other side of the same coin; because faith without doubt is not faith but certainty, and certainty, in the realm of the divine, is impossible; true faith includes doubt, embraces doubt, lives with doubt, and in that living with doubt, in that embracing of doubt, in that acceptance of doubt, becomes stronger, deeper, more real.", "و شروع کردم به فهمیدن، همچنین، که شک دشمن ایمان نیست، همانطور که بعضی باور دارند؛ شک همراه ایمان است، شریک ایمان، روی دیگر همان سکه؛ چون ایمان بدون شک ایمان نیست بلکه یقین است و یقین، در قلمرو الهی، ناممکن است؛ ایمان واقعی شامل شک است، شک را در آغوش می‌گیرد، با شک زندگی می‌کند و در آن زندگی کردن با شک، در آن در آغوش گرفتن شک، در آن پذیرش شک، قوی‌تر می‌شود، عمیق‌تر، واقعی‌تر."),
        StoryParagraph("And I began to understand, at last, why my father, despite his atheism, had been a good man; why my mother, despite her faith, had been a wise woman; why both of them, despite their differences, had loved me in the same way, with the same depth, with the same devotion; because faith and reason are not opposites, as the world believes; they are two paths to the same truth, two doors to the same room, two languages for the same prayer.", "و سرانجام شروع کردم به فهمیدن چرا پدرم، با وجود بی‌خدایی‌اش، مرد خوبی بوده؛ چرا مادرم، با وجود ایمانش، زنی فرزانه بوده؛ چرا هر دویشان، با وجود تفاوت‌هایشان، به همان شیوه دوستم داشتند، با همان عمق، با همان فداکاری؛ چون ایمان و عقل متضاد نیستند، همانطور که جهان باور دارد؛ دو راه به سوی همان حقیقت‌اند، دو در به همان اتاق، دو زبان برای همان دعا."),
        StoryParagraph("And I began to understand, most importantly, that God, or the divine, or whatever name we give to the mystery, does not care about our labels, does not care about our religions, does not care about the categories we create; God cares about our hearts, about our love, about our actions, about the way we treat each other; because the only true religion is love, the only true prayer is kindness, the only true worship is the act of being, in the deepest sense, human.", "و مهم‌تر از همه، شروع کردم به فهمیدن که خدا، یا الهی، یا هر نامی که به آن راز می‌دهیم، به برچسب‌هایمان اهمیت نمی‌دهد، به دین‌هایمان، به دسته‌بندی‌هایی که می‌سازیم؛ خدا به قلب‌هایمان اهمیت می‌دهد، به عشقمان، به اعمالمان، به شیوه‌ای که با هم رفتار می‌کنیم؛ چون تنها دین واقعی عشق است، تنها دعای واقعی مهربانی است، تنها پرستش واقعی عمل بودن است، در عمیق‌ترین معنا، انسان بودن."),
        StoryParagraph("I learned, in those weeks, to see the divine in the smallest things, in the flight of a bird, in the leap of a fish, in the color of the sunrise, in the depth of the night; and I learned to see the divine in the largest things, in the vastness of the ocean, in the infinity of the sky, in the mystery of the stars; and I learned that the divine is not more present in the largest than in the smallest, not more present in the spectacular than in the ordinary; the divine is equally present in all things, in every moment, in every breath.", "در آن هفته‌ها آموختم الهی را در کوچک‌ترین چیزها ببینم، در پرواز پرنده، در پرش ماهی، در رنگ طلوع خورشید، در عمق شب؛ و آموختم الهی را در بزرگ‌ترین چیزها ببینم، در وسعت اقیانوس، در بی‌نهایت آسمان، در راز ستارگان؛ و آموختم الهی در بزرگ‌ترین بیشتر از کوچک‌ترین حاضر نیست، در نمایشی بیشتر از عادی؛ الهی به‌طور برابر در همه چیز حاضر است، در هر لحظه، در هر نفس."),
        StoryParagraph("I learned, also, to be grateful; grateful for the sun, grateful for the water, grateful for the food, grateful for the boat, grateful for the tiger, grateful for my own life; and I learned that gratitude is not a sentiment but a practice, not a feeling but an action, not something that happens to us but something we choose to do, again and again, until it becomes a way of being.", "آموختم، همچنین، شاکر باشم؛ شاکر خورشید، شاکر آب، شاکر غذا، شاکر قایق، شاکر ببر، شاکر زندگی خودم؛ و آموختم شکرگزاری احساس نیست بلکه تمرین است، نه حس بلکه عمل، نه چیزی که برایمان اتفاق می‌افتد بلکه چیزی که انتخاب می‌کنیم انجام دهیم، بارها و بارها، تا وقتی شیوه‌ای از بودن شود."),
        StoryParagraph("And I learned that gratitude, when it becomes a way of being, transforms everything; it transforms the small into the sacred, the ordinary into the miraculous, the pain into the lesson, the loss into the gift; because when we are grateful, we see that everything, even the worst thing, even the most terrible thing, contains within it something worth thanking, something worth celebrating, something worth loving.", "و آموختم شکرگزاری، وقتی شیوه‌ای از بودن شود، همه چیز را دگرگون می‌کند؛ کوچک را مقدس می‌کند، عادی را معجزه‌آسا، درد را درس، فقدان را هدیه؛ چون وقتی شاکریم، می‌بینیم همه چیز، حتی بدترین چیز، حتی هولناک‌ترین چیز، در خودش چیزی دارد که ارزش شکر دارد، چیزی که ارزش جشن گرفتن دارد، چیزی که ارزش دوست داشتن دارد."),
        StoryParagraph("I began, in that time, to keep a different kind of diary; not just the record of what happened, not just the account of my survival; but a record of what I learned, a record of what I felt, a record of the presence that came to me in the night; and I wrote in that diary not with my hand but with my heart, not with words but with tears, not with ink but with the blood of my being.", "در آن زمان شروع کردم دفتر نوع متفاوتی نگه دارم؛ نه فقط ثبت آنچه اتفاق می‌افتاد، نه فقط گزارش بقایم؛ بلکه ثبت آنچه آموختم، ثبت آنچه حس کردم، ثبت حضوری که شبانه به سراغم می‌آمد؛ و در آن دفتر با دستم نمی‌نوشتم بلکه با قلبم، با کلمات نه بلکه با اشک، با مرکب نه بلکه با خون وجودم."),
        StoryParagraph("And I understood, at last, why the mystics of every faith have always written in poetry, not in prose; because the deepest truths cannot be expressed in ordinary language, cannot be captured in logical arguments, cannot be explained in rational discourse; the deepest truths can only be hinted at, can only be suggested, can only be approached sideways, obliquely, mysteriously.", "و سرانجام فهمیدم چرا عارفان هر ایمانی همیشه به شعر نوشته‌اند، نه به نثر؛ چون عمیق‌ترین حقایق را نمی‌شود در زبان عادی بیان کرد، در استدلال‌های منطقی گرفت، در گفتار عقلانی توضیح داد؛ عمیق‌ترین حقایق را فقط می‌شود اشاره کرد، فقط پیشنهاد، فقط از پهلو نزدیک شد، مایل، مرموز."),
        StoryParagraph("I began to see, in those days, that every religion I had ever known had been trying to say the same thing, in different ways, with different words, with different symbols; that the Hindu, the Christian, the Muslim, the Buddhist, the Jew, the atheist, all of them, at their best, were reaching toward the same mystery, the same truth, the same divine.", "در آن روزها شروع کردم به دیدن که هر دینی که تا حالا شناخته بودم تلاش کرده بود همان چیز را بگوید، به شیوه‌های متفاوت، با کلمات متفاوت، با نمادهای متفاوت؛ که هندو، مسیحی، مسلمان، بودایی، یهودی، بی‌خدا، همه‌شان، در بهترین حالتشان، به سوی همان راز می‌رسیدند، همان حقیقت، همان الهی."),
        StoryParagraph("And I understood, at last, why I had never been able to choose one faith over another; because choosing one would have meant rejecting the others, and I could not reject the others, because the others were also true, also beautiful, also sacred; because God, if God existed, was too vast, too infinite, too mysterious, to be contained in any single tradition, any single book, any single name.", "و سرانجام فهمیدم چرا هرگز نتوانسته بودم یک ایمان را بر دیگری برگزینم؛ چون برگزیدن یکی به معنای رد کردن دیگران بود و نمی‌توانستم دیگران را رد کنم، چون دیگران هم درست بودند، هم زیبا، هم مقدس؛ چون خدا، اگر وجود داشت، بیش از حد وسیع بود، بیش از حد بی‌نهایت، بیش از حد مرموز، که در هیچ سنت واحدی، هیچ کتاب واحدی، هیچ نام واحدی جا شود."),
        StoryParagraph("I began, in that time, to pray again; but I prayed differently than I had prayed before; not with the formal prayers of the temple, not with the creeds of the church, not with the verses of the mosque; but with my own words, my own heart, my own soul; and I found that my prayers, my simple, imperfect prayers, were as accepted, as heard, as answered, as any formal prayer could ever be.", "در آن زمان شروع کردم دوباره دعا کنم؛ اما متفاوت از قبل دعا کردم؛ نه با دعاهای رسمی معبد، نه با اعتقادنامه‌های کلیسا، نه با آیات مسجد؛ بلکه با کلمات خودم، قلب خودم، روح خودم؛ و یافتم که دعاهایم، دعاهای ساده و ناقصم، به همان اندازه پذیرفته، شنیده، پاسخ‌داده بودند که هر دعای رسمی می‌تواند باشد."),
        StoryParagraph("I began to understand, at last, that God does not care about the words we use, does not care about the languages we speak, does not care about the rituals we perform; God cares about the love behind the words, the sincerity behind the languages, the devotion behind the rituals; because God is not a judge but a lover, not a king but a parent, not a distant deity but an intimate presence.", "سرانجام شروع کردم به فهمیدن که خدا به کلماتی که استفاده می‌کنیم اهمیت نمی‌دهد، به زبان‌هایی که صحبت می‌کنیم، به آیین‌هایی که انجام می‌دهیم؛ خدا به عشق پشت کلمات اهمیت می‌دهد، به صداقت پشت زبان‌ها، به فداکاری پشت آیین‌ها؛ چون خدا قاضی نیست بلکه عاشق است، پادشاه نیست بلکه والد، خدای دور نیست بلکه حضور نزدیک."),
        StoryParagraph("I began to see, in those weeks, that the presence I felt was not separate from me, not outside of me, not distant from me; the presence was within me, was part of me, was the deepest part of me, the part that I had always been, the part that I had never known; and in that understanding, in that recognition, in that reunion, I found a peace that I had never known, a peace that passed all understanding, a peace that was, in itself, a kind of home.", "در آن هفته‌ها شروع کردم به دیدن که حضوری که حس می‌کردم از من جدا نبود، بیرون از من، دور از من؛ حضور در من بود، بخشی از من بود، عمیق‌ترین بخش من، بخشی که همیشه بوده بودم، بخشی که هرگز نمی‌شناختم؛ و در آن فهم، در آن تشخیص، در آن پیوند دوباره، آرامشی یافتم که هرگز نشناخته بودم، آرامشی که فراتر از هر فهمی بود، آرامشی که، به خودی خود، نوعی خانه بود."),
        StoryParagraph("And I understood, at last, what Jesus meant when he said that the kingdom of God is within you; what the Buddha meant when he said that we are already enlightened; what the Hindu sages meant when they said that Atman is Brahman; what the Muslim mystics meant when they said that the beloved and the lover are one.", "و سرانجام فهمیدم عیسی وقتی گفت پادشاهی خدا در درون شماست منظورش چه بود؛ بودا وقتی گفت ما از قبل روشن‌ضمیریم، فرزانگان هندو وقتی گفتند آتمن برهمن است، عارفان مسلمان وقتی گفتند معشوق و عاشق یکی هستند."),
        StoryParagraph("And I understood, also, why I had to lose everything to find this; why I had to be stripped of all my possessions, of all my relationships, of all my identities, of all my beliefs; because only when we have nothing left, only when we are nothing left, can we discover what we truly are, what we have always been, what we will always be.", "و فهمیدم، همچنین، چرا باید همه چیز را از دست می‌دادم تا این را بیابم؛ چرا باید از همه دارایی‌هایم خلع می‌شدم، از همه روابطم، از همه هویت‌هایم، از همه باورهایم؛ چون تنها وقتی هیچ چیز برایمان نمانده، تنها وقتی هیچ چیزی از ما نمانده، می‌توانیم کشف کنیم واقعاً چه هستیم، همیشه چه بوده‌ایم، همیشه چه خواهیم بود."),
        StoryParagraph("And so the days passed, and the nights passed, and the weeks passed, and I continued, not just to survive, but to live; not just to endure, but to be; not just to be present, but to be present to the presence; and I found, in that living, in that being, in that presence, everything that I had been seeking all my life, without knowing what I was seeking, without knowing where I was seeking it, without knowing what I would find.", "و اینگونه روزها گذشتند و شب‌ها گذشتند و هفته‌ها گذشتند و ادامه دادم، نه فقط به بقا، بلکه به زندگی؛ نه فقط به تحمل، بلکه به بودن؛ نه فقط به حاضر بودن، بلکه به حاضر بودن برای حضور؛ و در آن زندگی، در آن بودن، در آن حضور، هر چیزی که تمام عمرم در جستجویش بودم را یافتم، بی‌آنکه بدانم چه می‌جویم، بی‌آنکه بدانم کجا می‌جویمش، بی‌آنکه بدانم چه می‌یابم."),
        StoryParagraph("And what I found, what I truly found, was this: that the universe is not indifferent, as I had feared; that the universe is not cruel, as I had believed; that the universe is not meaningless, as I had suspected; the universe is alive, is conscious, is loving; the universe is, in the deepest sense, a presence, a presence that knows us, that cares for us, that loves us, that has always loved us, that will always love us.", "و آنچه یافتم، آنچه به‌راستی یافتم، این بود: که جهان بی‌تفاوت نیست، همانطور که ترسیده بودم؛ که جهان بی‌رحم نیست، همانطور که باور کرده بودم؛ که جهان بی‌معنا نیست، همانطور که گمان کرده بودم؛ جهان زنده است، آگاه است، عاشق است؛ جهان، در عمیق‌ترین معنا، حضور است، حضوری که ما را می‌شناسد، که به ما اهمیت می‌دهد، که دوستمان می‌دارد، که همیشه دوستمان داشته، که همیشه دوستمان خواهد داشت."),
        StoryParagraph("And I wept, when I understood this, wept not because I was sad but because I was overwhelmed, wept not because I had lost but because I had found, wept not because I was alone but because I knew, at last, that I had never been alone, that I had never been abandoned, that I had never been forgotten.", "و گریستم، وقتی این را فهمیدم، گریستم نه چون غمگین بودم بلکه چون مقهور شده بودم، گریستم نه چون از دست داده بودم بلکه چون یافته بودم، گریستم نه چون تنها بودم بلکه چون سرانجام می‌دانستم هرگز تنها نبوده‌ام، هرگز رها نشده‌ام، هرگز فراموش نشده‌ام."),
        StoryParagraph("And Richard Parker, in that moment, turned and looked at me; and I looked back, and in that look, in that exchange, in that meeting of eyes, I saw something I had never seen before; I saw understanding, I saw recognition, I saw a kind of love that was not human and was not animal but something in between, something that transcended both, something that was, in its own strange way, divine.", "و ریچارد پارکر در آن لحظه چرخید و نگاهم کرد؛ و من هم نگاهش کردم و در آن نگاه، در آن تبادل، در آن دیدار چشم‌ها، چیزی دیدم که هرگز قبلاً ندیده بودم؛ فهمیدم، تشخیص دادم، نوعی عشق دیدم که انسانی نبود و حیوانی نبود بلکه چیزی در بین، چیزی که از هر دو فراتر می‌رفت، چیزی که، به شیوه عجیب خودش، الهی بود."),
        StoryParagraph("And I understood, at last, that this was the final lesson, the lesson that the ocean had been teaching me all along, the lesson that I had been too blind to see: that everything is connected, that everything is one, that the tiger and the boy, the ocean and the sky, the life and the death, the joy and the grief, are all part of the same reality, all expressions of the same presence, all faces of the same divine.", "و سرانجام فهمیدم که این آخرین درس بود، درسی که اقیانوس تمام مدت به من می‌آموخت، درسی که بیش از حد کور بودم که ببینم: که همه چیز به هم پیوسته است، که همه چیز یکی است، که ببر و پسر، اقیانوس و آسمان، زندگی و مرگ، شادی و اندوه، همه بخشی از همان واقعیت‌اند، همه تجلی همان حضور، همه چهره‌های همان الهی."),
        StoryParagraph("And in that understanding, in that realization, in that final awakening, I found a peace that nothing could disturb, a joy that nothing could diminish, a love that nothing could destroy; and I knew, with a certainty that came not from the mind but from the heart, that I would survive, that I would return, that I would live to tell this story.", "و در آن فهم، در آن درک، در آن بیداری نهایی، آرامشی یافتم که هیچ چیز نمی‌توانست مختلش کند، شادی‌ای که هیچ چیز نمی‌توانست کمش کند، عشقی که هیچ چیز نمی‌توانست نابودش کند؛ و می‌دانستم، با یقینی که نه از ذهن بلکه از قلب می‌آمد، که زنده می‌مانم، که بازمی‌گردم، که زنده می‌مانم تا این داستان را بگویم."),
        StoryParagraph("And so the days continued, and the nights continued, and the weeks continued, and the tiger and the boy continued, and the ocean continued, and the presence continued; and in that continuing, in that enduring, in that being, I found the meaning of everything, the answer to every question, the truth behind every mystery.", "و اینگونه روزها ادامه یافتند و شب‌ها ادامه یافتند و هفته‌ها ادامه یافتند و ببر و پسر ادامه یافتند و اقیانوس ادامه یافت و حضور ادامه یافت؛ و در آن ادامه، در آن تحمل، در آن بودن، معنای همه چیز را یافتم، پاسخ هر پرسشی، حقیقت پشت هر رازی."),
        StoryParagraph("And that meaning, that answer, that truth, was simply this: that we are loved, that we have always been loved, that we will always be loved; and that this love, this divine love, is the only thing that matters, the only thing that is real, the only thing that endures.", "و آن معنا، آن پاسخ، آن حقیقت، به‌سادگی این بود: که ما دوست داشته می‌شویم، که همیشه دوست داشته شده‌ایم، که همیشه دوست داشته خواهیم شد؛ و این عشق، این عشق الهی، تنها چیزی است که اهمیت دارد، تنها چیزی که واقعی است، تنها چیزی که می‌ماند."),
        StoryParagraph("And so the story continues, into the next chapter, into the next trial, into the next lesson, into the next revelation; for the ocean, like life, never stops teaching, never stops giving, never stops loving.", "و اینگونه داستان ادامه می‌یابد، به فصل بعد، به آزمون بعد، به درس بعد، به مکاشفه بعد؛ چون اقیانوس، همچون زندگی، هرگز از آموزش دست نمی‌کشد، هرگز از دادن، هرگز از عشق ورزیدن."),
    )
)
// ─────────── فصل ۵: جزیره ───────────
private fun chapter5() = StoryChapter(
    number = 5, title = "The Island", titlePersian = "جزیره",
    paragraphs = listOf(
        StoryParagraph("It was on the two hundred and twenty-seventh day, or perhaps it was the two hundred and twenty-eighth, for I had long since lost track of time, that I saw it: a green smudge on the horizon, a small dark shape that grew slowly larger as the current carried us toward it, a shape that I first took to be a hallucination, because I had been hallucinating for weeks by then, and I had learned not to trust my own eyes.", "در روز دویست و بیست و هفتم بود، یا شاید دویست و بیست و هشتم، چون مدت‌ها پیش از دست دادن حساب زمان گذشته بود، که دیدمش: لکه‌ای سبز در افق، شکل کوچکی تاریک که آهسته بزرگ‌تر می‌شد همانطور که جریان ما را به سمتش می‌برد، شکلی که نخست توهم پنداشتم، چون تا آن موقع هفته‌ها بود که توهم می‌دیدم و آموخته بودم به چشمان خودم اعتماد نکنم."),
        StoryParagraph("I had, by then, experienced many hallucinations; I had seen ships that turned out to be clouds, I had heard voices that turned out to be the wind, I had smelled food that turned out to be the salt in the air; my mind, starved and exhausted and desperate, had begun to invent things, to create its own reality, to fill the emptiness of the ocean with the fullness of imagination.", "تا آن موقع توهم‌های بسیاری تجربه کرده بودم؛ کشتی‌هایی دیده بودم که ابر بودند، صداهایی شنیده بودم که باد بودند، بویی از غذا حس کرده بودم که نمک هوا بود؛ ذهنم، گرسنه و خسته و درمانده، شروع کرده بود به اختراع کردن، به آفریدن واقعیت خودش، به پر کردن تهی‌بودن اقیانوس با پُری خیال."),
        StoryParagraph("But this time, as the shape grew larger and more distinct, I began to suspect that it was real; I began to see colors that no hallucination had ever shown me, greens and browns and the dark silver of tree trunks; I began to smell things that no hallucination had ever smelled, the rich, damp, living smell of vegetation, the smell of earth, the smell of life.", "اما این بار، همانطور که شکل بزرگ‌تر و واضح‌تر می‌شد، شروع کردم به گمان کردن که واقعی است؛ شروع کردم به دیدن رنگ‌هایی که هیچ توهمی هرگز نشانم نداده بود، سبزها و قهوه‌ای‌ها و نقره‌ای تیره تنه درختان؛ شروع کردم به بوییدن چیزهایی که هیچ توهمی هرگز نبویده بود، بوی غنی و مرطوب و زنده گیاهان، بوی خاک، بوی زندگی."),
        StoryParagraph("And I began to weep, because I knew, with a certainty that came from somewhere deeper than thought, that I had found what I had been looking for, that the ocean was about to give me what it had been withholding, that the story of the boy and the tiger and the raft was about to reach a new chapter, a chapter that neither of us could have predicted.", "و شروع کردم به گریه کردن، چون می‌دانستم، با یقینی که از جایی عمیق‌تر از اندیشه می‌آمد، که آنچه در جستجویش بودم را یافته بودم، که اقیانوس در شرف دادن چیزی بود که تا آن موقع دریغش کرده بود، که داستان پسر و ببر و کلک در شرف رسیدن به فصلی نو بود، فصلی که هیچ‌کدام نمی‌توانستیم پیش‌بینی‌اش کنیم."),
        StoryParagraph("The island was small, no more than a mile across, and it was covered in trees, in the sort of trees that grow on islands in the Pacific, tall and green and dense; and I could see, as we approached, that it was surrounded by a fringe of sandy beach, and that the beach was surrounded by water that was lighter than the water of the open ocean, water that spoke of a shallow bottom, water that spoke of safety.", "جزیره کوچک بود، بیشتر از یک مایل عرض نداشت و پوشیده از درختان بود، همان نوع درختانی که در جزایر اقیانوس آرام می‌رویند، بلند و سبز و انبوه؛ و همانطور که نزدیک می‌شدیم، می‌توانستم ببینم که حاشیه‌ای از ساحل شنی احاطه‌اش کرده و ساحل توسط آبی احاطه شده که از آب اقیانوس باز روشن‌تر بود، آبی که از بستر کم‌عمق حرف می‌زد، از امنیت."),
        StoryParagraph("Richard Parker saw the island, too; I know he did, because I saw him lift his head, I saw him sniff the air, I saw his eyes narrow; and I saw, in that moment, something that I had not seen in him before: a kind of hope, a kind of recognition, a kind of joy that was not the joy of the hunt but the joy of the home, the joy of a creature returning to something it had known in another life, in another time, in another world.", "ریچارد پارکر هم جزیره را دید؛ می‌دانم دید، چون دیدم سرش را بلند کرد، دیدم هوا را بو کشید، دیدم چشمانش باریک شد؛ و در آن لحظه، چیزی در او دیدم که قبلاً ندیده بودم: نوعی امید، نوعی تشخیص، نوعی شادی که نه شادی شکار بود بلکه شادی خانه، شادی موجودی که به چیزی بازمی‌گشت که در زندگی دیگر، در زمان دیگر، در جهان دیگر شناخته بود."),
        StoryParagraph("The current carried us, gently, toward the beach; I could feel the raft moving with a purpose that it had not had before, with a direction that it had not known before, with a speed that was not the speed of drifting but the speed of arrival; and I knew, in that moment, that we had been traveling toward this island all along, that the ocean had been guiding us, that the presence had been leading us, that everything that had happened had been leading to this.", "جریان ما را به‌آرامی به سمت ساحل برد؛ می‌توانستم حس کنم کلک با هدفی حرکت می‌کند که قبلاً نداشته بود، با جهتی که قبلاً نمی‌شناخت، با سرعتی که سرعت رانده شدن نبود بلکه سرعت رسیدن؛ و در آن لحظه می‌دانستم که تمام مدت به سمت این جزیره سفر می‌کردیم، که اقیانوس راهنمایمان بود، که حضور رهبریمان می‌کرد، که هر چیزی که اتفاق افتاده بود ما را به اینجا می‌رساند."),
        StoryParagraph("The raft touched the sand, and I climbed off, and my legs, unaccustomed to solid ground, buckled beneath me; I fell to my knees, and I kissed the sand, and I wept, and I thanked the ocean, and I thanked the presence, and I thanked the tiger, and I thanked everything and everyone that had brought me to this place.", "کلک به ماسه رسید و من پایین آمدم و پاهایم، ناآشنا با زمین سخت، زیرم خم شد؛ به زانو افتادم و ماسه را بوسیدم و گریستم و از اقیانوس تشکر کردم و از حضور تشکر کردم و از ببر تشکر کردم و از هر چیزی و هر کسی که مرا به اینجا آورده بود تشکر کردم."),
        StoryParagraph("I had not touched land in seven months, had not felt anything solid under my feet in seven months, had not smelled earth in seven months, had not seen green in seven months; and now, suddenly, all of it came to me at once, a flood of sensations that overwhelmed my body, that overwhelmed my mind, that overwhelmed my soul.", "هفت ماه بود زمین را لمس نکرده بودم، زیر پایم چیزی سخت حس نکرده بودم، خاک نبوییده بودم، سبزی ندیده بودم؛ و حالا، به‌ناگاه، همه‌اش یکجا به من رسید، سیلابی از حس‌ها که بدنم را مقهور کرد، ذهنم را، روحم را."),
        StoryParagraph("I stood up, slowly, shakily, and I looked around; the island was more beautiful than anything I had ever seen, more beautiful than the zoo of my childhood, more beautiful than the gardens of Pondicherry, more beautiful than any place I had ever known or imagined; and I understood, in that moment, what paradise means, what the ancients meant when they spoke of the Elysian fields, what every faith has tried to describe when it has spoken of heaven.", "آهسته، لرزان، بلند شدم و دور و برم را نگاه کردم؛ جزیره از هر چیزی که تا حالا دیده بودم زیباتر بود، از باغ‌وحش کودکی‌ام، از باغ‌های پودوچری، از هر جایی که تا به حال شناخته یا تصور کرده بودم؛ و در آن لحظه فهمیدم بهشت یعنی چه، گذشتگان چه می‌گفتند وقتی از دشت‌های الیزیایی حرف می‌زدند، هر ایمانی چه تلاش کرده توصیفش کند وقتی از بهشت گفته."),
        StoryParagraph("But the island was not only beautiful, it was also alive, more alive than any place I had ever been; I could hear the birds singing in the trees, I could hear the insects buzzing in the air, I could hear the waves lapping against the shore; and I could feel, beneath my feet, the heartbeat of the earth, the pulse of the world, the breath of the divine.", "اما جزیره فقط زیبا نبود، زنده هم بود، زنده‌تر از هر جایی که تا حالا بوده‌ام؛ می‌توانستم پرندگان را بشنوم که در درختان می‌خوانند، حشرات را که در هوا وزوز می‌کنند، امواج را که به ساحل می‌خورند؛ و زیر پایم می‌توانستم تپش زمین را حس کنم، نبض جهان، نفس الهی."),
        StoryParagraph("I explored the island, cautiously, carefully, because I had learned on the ocean that safety was an illusion, that danger was always present, that even the most beautiful places could conceal the most terrible threats; and as I explored, I found things that surprised me, things that delighted me, things that puzzled me.", "جزیره را کاویدم، با احتیاط، با دقت، چون روی اقیانوس آموخته بودم که امنیت توهمی است، که خطر همیشه حاضر است، که حتی زیباترین جاها می‌توانند هولناک‌ترین تهدیدها را پنهان کنند؛ و همانطور که می‌کاویدم، چیزهایی یافتم که شگفت‌زده‌ام کرد، خوشحالم کرد، حیرانم کرد."),
        StoryParagraph("I found fresh water, in a small pool near the center of the island, water so clear and so pure that I could see the bottom, water that tasted sweeter than any water I had ever tasted; I drank, deeply, greedily, and I wept, again, from gratitude, from relief, from the simple joy of drinking without fear.", "آب شیرین یافتم، در حوضچه‌ای کوچک نزدیک مرکز جزیره، آبی چنان زلال و چنان پاک که می‌توانستم کفش را ببینم، آبی که از هر آبی که تا حالا چشیده بودم شیرین‌تر بود؛ نوشیدم، عمیق، حریصانه و دوباره گریستم، از سپاسگزاری، از آسودگی، از شادی ساده نوشیدن بدون ترس."),
        StoryParagraph("I found food, in abundance, food such as I had never imagined on the ocean; fruits hanging from the trees, berries growing in the bushes, roots that I could dig from the ground, algae that I could eat raw; and I ate, and I ate, and I ate, until my stomach, unused to such plenty, protested, and I had to stop, and I laughed, for the first time in months, I laughed.", "غذا یافتم، به فراوانی، غذایی که روی اقیانوس هرگز تصورش را نکرده بودم؛ میوه‌هایی که از درختان آویزان بودند، توت‌هایی که در بوته‌ها می‌روییدند، ریشه‌هایی که می‌توانستم از زمین بکنم، جلبک‌هایی که می‌توانستم خام بخورم؛ و خوردم و خوردم و خوردم تا شکمم، ناآشنا با چنین فراوانی، اعتراض کرد و مجبور شدم متوقف شوم و خندیدم، برای نخستین بار در ماه‌ها، خندیدم."),
        StoryParagraph("I found shelter, in the hollow of a great tree, a hollow that was just large enough for a boy and just small enough to be safe; I made a bed of leaves, I made a pillow of moss, I made a home; and I slept, for the first time in seven months, I slept without fear, without the sounds of the ocean in my ears, without the smell of salt in my nose, without the knowledge that death was only a wave away.", "سرپناه یافتم، در حفره درخت بزرگی، حفره‌ای که به‌اندازه کافی برای پسری بزرگ بود و به‌اندازه کافی کوچک که امن باشد؛ تختی از برگ ساختم، بالشی از خزه، خانه‌ای ساختم؛ و خوابیدم، برای نخستین بار در هفت ماه، بدون ترس خوابیدم، بدون صدای اقیانوس در گوش‌هایم، بدون بوی نمک در بینی‌ام، بدون دانستن اینکه مرگ تنها یک موج آن‌طرف‌تر است."),
        StoryParagraph("But I did not forget Richard Parker, not for a moment; because Richard Parker was still in the lifeboat, still my companion, still my responsibility; and I knew that if I wanted to stay on this island, I would have to find a way to live with him here, to share this paradise with him, to make a home for both of us.", "اما ریچارد پارکر را فراموش نکردم، نه یک لحظه؛ چون ریچارد پارکر هنوز در قایق نجات بود، هنوز همسفرم، هنوز مسئولیتم؛ و می‌دانستم اگر می‌خواهم در این جزیره بمانم، باید راهی بیابم که با او اینجا زندگی کنم، این بهشت را با او قسمت کنم، برای هر دویمان خانه‌ای بسازم."),
        StoryParagraph("I approached the lifeboat, carefully, as I had learned to do; I called to Richard Parker, softly, as I had learned to do; and I waited, patiently, as I had learned to do; and slowly, very slowly, he came out, and he stepped onto the sand, and he stood there, in the sunlight, and he looked around, and he seemed, in that moment, almost gentle.", "به قایق نجات نزدیک شدم، با احتیاط، همانطور که آموخته بودم؛ آرام صدایش کردم، همانطور که آموخته بودم؛ و منتظر ماندم، با صبر، همانطور که آموخته بودم؛ و آهسته، بسیار آهسته، بیرون آمد و روی ماسه قدم گذاشت و آنجا در آفتاب ایستاد و دور و برش را نگاه کرد و در آن لحظه تقریباً ملایم به نظر می‌رسید."),
        StoryParagraph("He walked into the forest, and I followed him, at a distance, as I had learned to do; and I watched him explore, watched him sniff, watched him mark his territory; and I understood, in that moment, that this was his island, too, that he had as much right to be here as I did, that we were both creatures of this world, both children of this universe, both manifestations of the same divine.", "به جنگل رفت و من دنبالش کردم، از فاصله، همانطور که آموخته بودم؛ و تماشا کردم که می‌کاوید، بو می‌کشید، قلمروش را علامت‌گذاری می‌کرد؛ و در آن لحظه فهمیدم که این هم جزیره اوست، که او هم به اندازه من حق دارد اینجا باشد، که هر دویمان موجوداتی از این جهانیم، فرزندانی از این جهان، تجلی‌هایی از همان الهی."),
        StoryParagraph("The days on the island were the happiest of my life, or at least the happiest that I can remember; I had food, I had water, I had shelter, I had rest; I had time to think, time to pray, time to write, time to be; and I had Richard Parker, whose presence, which had once been a terror, had become, in the strangest way, a comfort, a companionship, a kind of love.", "روزها در جزیره شادترین روزهای زندگی‌ام بودند، یا حداقل شادترین روزهایی که می‌توانم به یاد آورم؛ غذا داشتم، آب داشتم، سرپناه داشتم، استراحت داشتم؛ زمان برای فکر کردن داشتم، برای دعا کردن، برای نوشتن، برای بودن؛ و ریچارد پارکر را داشتم، که حضورش، که زمانی وحشت بود، به عجیب‌ترین شیوه، تسلی شده بود، همراهی، نوعی عشق."),
        StoryParagraph("I explored the island every day, and every day I found something new; a cave that I had not seen before, a tree that bore fruit I had not tasted, a bird that sang a song I had not heard; and every night, I returned to my shelter, and I ate my dinner, and I wrote in my diary, and I slept, and I dreamed, and in my dreams I saw my mother, and I saw my father, and I saw my brother, and they were well, and they were happy, and they were waiting for me.", "هر روز جزیره را می‌کاویدم و هر روز چیز جدیدی می‌یافتم؛ غاری که قبلاً ندیده بودم، درختی که میوه‌ای می‌داد که نچشیده بودم، پرنده‌ای که آوازی می‌خواند که نشنیده بودم؛ و هر شب به سرپناهم بازمی‌گشتم و شامم را می‌خوردم و در دفترم می‌نوشتم و می‌خوابیدم و خواب می‌دیدم و در خواب‌هایم مادرم را می‌دیدم و پدرم را و برادرم را و آن‌ها خوب بودند و خوشحال و منتظرم بودند."),
        StoryParagraph("But there was something strange about the island, something that I could not quite name, something that troubled me in the quiet hours of the night; the animals, I noticed, were fewer than they should have been; the birds did not sing as loudly as they should have; the insects, which should have been everywhere, were strangely absent; and the trees, though green, seemed, in a certain light, to be watching.", "اما چیز عجیبی درباره جزیره بود، چیزی که کاملاً نمی‌توانستم نامش را ببرم، چیزی که در ساعات آرام شب آشفته‌ام می‌کرد؛ حیوانات، متوجه شدم، کمتر از آنچه باید بودند؛ پرندگان به بلندی‌ای که باید نمی‌خواندند؛ حشرات، که باید همه‌جا می‌بودند، به‌طرز عجیبی غایب بودند؛ و درختان، هرچند سبز، در نوری خاص، به نظر می‌رسید تماشا می‌کنند."),
        StoryParagraph("And then, one night, I discovered the truth, the terrible truth, the truth that would change everything; I had climbed a tree, to sleep in its branches, to be safe from whatever might walk the forest floor; and as I lay there, in the dark, I saw something that I will never forget: the trees were moving, the trees were alive, the trees were eating.", "و سپس، یک شبی، حقیقت را کشف کردم، حقیقت هولناک، حقیقتی که همه چیز را تغییر می‌داد؛ از درختی بالا رفته بودم تا در شاخه‌هایش بخوابم، تا از هر چه ممکن بود در کف جنگل قدم بزند در امان باشم؛ و همانطور که آنجا دراز کشیده بودم، در تاریکی، چیزی دیدم که هرگز فراموش نمی‌کنم: درختان حرکت می‌کردند، درختان زنده بودند، درختان می‌خوردند."),
        StoryParagraph("The island, I realized, was carnivorous; the island, I realized, was a living thing, a creature of its own, a being that fed on the animals that came to it; and the fruit that I had been eating, the fruit that I had thought was a gift, was in fact a lure, a trap, a bait that the island used to attract its prey.", "جزیره، دریافتم، گوشت‌خوار بود؛ جزیره، دریافتم، موجودی زنده بود، موجودی از خودش، موجودی که از حیواناتی که به آن می‌آمدند تغذیه می‌کرد؛ و میوه‌ای که می‌خوردم، میوه‌ای که فکر می‌کردم هدیه است، در واقع طعمه بود، تله، بیتی که جزیره برای جذب شکارش استفاده می‌کرد."),
        StoryParagraph("I had eaten the fruit, I had slept in the tree, I had been, for weeks, the island's guest; and I understood, at last, why there were no old animals on the island, why there were no remains, why there were no bones; because the island consumed everything, because the island left no trace, because the island was, in its own way, the most terrible thing I had ever encountered.", "میوه را خورده بودم، در درخت خوابیده بودم، هفته‌ها مهمان جزیره بودم؛ و سرانجام فهمیدم چرا حیوانات پیر در جزیره نبودند، چرا بقایایی نبود، چرا استخوانی نبود؛ چون جزیره همه چیز را می‌خورد، چون جزیره اثری باقی نمی‌گذاشت، چون جزیره، به شیوه خودش، هولناک‌ترین چیزی بود که تا حالا با آن روبرو شده بودم."),
        StoryParagraph("I fled that night, fled the island, fled the paradise that was also a hell; I called to Richard Parker, and he came, and we boarded the lifeboat, and we pushed off from the shore, and we drifted, once again, into the open ocean, into the vastness, into the emptiness, into the unknown.", "آن شب گریختم، از جزیره گریختم، از بهشتی که دوزخ هم بود گریختم؛ ریچارد پارکر را صدا کردم و آمد و سوار قایق نجات شدیم و از ساحل دور شدیم و دوباره به اقیانوس باز رانده شدیم، به وسعت، به تهی‌بودن، به ناشناخته."),
        StoryParagraph("And yet, even as I fled, I did not regret the time I had spent there; because the island had given me something, even as it had tried to take everything; the island had given me rest, had given me food, had given me water, had given me a glimpse of what peace might look like; and I understood, at last, that even the most terrible things can be gifts, can be teachers, can be part of the path that leads us home.", "و با این حال، حتی همانطور که می‌گریختم، از زمانی که آنجا گذرانده بودم پشیمان نبودم؛ چون جزیره چیزی به من داده بود، حتی همانطور که تلاش کرده بود همه چیز را بگیرد؛ جزیره به من استراحت داده بود، غذا، آب، نگاهی از اینکه آرامش چه شکلی است؛ و سرانجام فهمیدم که حتی هولناک‌ترین چیزها می‌توانند هدیه باشند، معلم، بخشی از راهی که ما را به خانه می‌رساند."),
        StoryParagraph("The days after the island were the hardest, harder than the days before, because I had tasted peace and had it taken from me; because I had seen hope and had it destroyed; because I had, for the first time in months, believed that my ordeal might be over, only to discover that it was not, that it might never be, that I might drift forever, might die in the middle of the ocean, might be forgotten by the world.", "روزهای بعد از جزیره سخت‌ترین بودند، سخت‌تر از روزهای پیش از آن، چون طعم آرامش را چشیده بودم و از من گرفته شده بود؛ چون امید دیده بودم و نابود شده بود؛ چون برای نخستین بار در ماه‌ها باور کرده بودم که مصیبتم ممکن است تمام شده باشد، فقط برای کشف اینکه نشده، ممکن است هرگز نشود، ممکن است تا ابد سرگردان باشم، ممکن است در میانه اقیانوس بمیرم، ممکن است توسط جهان فراموش شوم."),
        StoryParagraph("And yet, even in that despair, even in that darkness, even in that emptiness, I did not lose hope; because I had learned, on the ocean, on the island, in the presence, that hope is not a thing that circumstances give us, but a thing that we choose; hope is not a feeling but a decision, not an emotion but a commitment, not a state but a practice.", "و با این حال، حتی در آن ناامیدی، حتی در آن تاریکی، حتی در آن تهی‌بودن، امید را از دست ندادم؛ چون روی اقیانوس، روی جزیره، در حضور، آموخته بودم که امید چیزی نیست که شرایط به ما می‌دهد، بلکه چیزی است که انتخاب می‌کنیم؛ امید احساس نیست بلکه تصمیم است، عاطفه نیست بلکه تعهد، حالت نیست بلکه تمرین."),
        StoryParagraph("I chose to hope; I chose to believe that the ocean would lead me somewhere, that the story would have an end, that the suffering would, at last, have meaning; and in that choice, in that belief, in that hope, I found the strength to continue, the strength to endure, the strength to live one more day, and then one more, and then one more.", "انتخاب کردم امید داشته باشم؛ انتخاب کردم باور کنم که اقیانوس مرا به جایی می‌برد، که داستان پایانی دارد، که رنج، سرانجام، معنا خواهد داشت؛ و در آن انتخاب، در آن باور، در آن امید، قدرتی برای ادامه دادن یافتم، قدرتی برای تحمل، قدرتی برای یک روز دیگر زندگی کردن، و بعد یکی دیگر، و بعد یکی دیگر."),
        StoryParagraph("And so the days passed, and the nights passed, and the weeks passed, and the ocean passed beneath us, endless and eternal, indifferent and alive; and I continued, and Richard Parker continued, and the raft continued, and the story continued, into the unknown, into the future, into whatever waited for us on the other side of the horizon.", "و اینگونه روزها گذشتند و شب‌ها گذشتند و هفته‌ها گذشتند و اقیانوس زیرمان گذشت، بی‌پایان و ابدی، بی‌تفاوت و زنده؛ و من ادامه دادم و ریچارد پارکر ادامه داد و کلک ادامه داد و داستان ادامه یافت، به ناشناخته، به آینده، به هر آنچه آن‌سوی افق منتظرمان بود."),
        StoryParagraph("I do not know how many more days passed, do not know how many more nights I spent on that raft, do not know how many more times I thought I would die and was surprised to find myself alive; all I know is that the ocean, at last, had mercy on us, at last, gave us what we had been seeking, at last, brought us to the end of the beginning and the beginning of the end.", "نمی‌دانم چند روز دیگر گذشت، نمی‌دانم چند شب دیگر روی آن کلک گذراندم، نمی‌دانم چند بار دیگر فکر کردم می‌میرم و شگفت‌زده شدم که زنده‌ام؛ تنها می‌دانم اقیانوس، سرانجام، به ما رحم کرد، سرانجام، چیزی که در جستجویش بودیم را به ما داد، سرانجام، ما را به پایان آغاز و آغاز پایان رساند."),
        StoryParagraph("It was on the two hundred and twenty-seventh day, or perhaps it was the two hundred and twenty-eighth, I do not remember precisely, that we saw land; not the small green smudge of the island, not the low dark shape of a distant shore, but the tall buildings of a city, the smoke of chimneys, the shapes of men and machines; and I wept, and I laughed, and I prayed, and I thanked every god I had ever known.", "در روز دویست و بیست و هفتم بود، یا شاید دویست و بیست و هشتم، دقیق یادم نیست، که خشکی دیدیم؛ نه لکه کوچک سبز جزیره، نه شکل کوچک تاریک ساحلی دور، بلکه ساختمان‌های بلند شهری، دود دودکش‌ها، شکل مردان و ماشین‌ها؛ و گریستم و خندیدم و دعا کردم و از هر خدایی که تا حالا شناخته بودم تشکر کردم."),
        StoryParagraph("The lifeboat drifted to shore, and I stepped onto the sand of Mexico, onto the sand of the New World, onto the sand of a life that I had never imagined and that I would, from that day forward, have to learn to live; and I fell to my knees, and I kissed the ground, and I wept, and I thanked the ocean, and I thanked the tiger, and I thanked the presence, and I thanked everything and everyone that had brought me here.", "قایق نجات به ساحل رانده شد و من روی ماسه مکزیک قدم گذاشتم، روی ماسه جهان نو، روی ماسه زندگی‌ای که هرگز تصور نکرده بودم و از آن روز به بعد، باید یاد می‌گرفتم زندگی‌اش کنم؛ و به زانو افتادم و زمین را بوسیدم و گریستم و از اقیانوس تشکر کردم و از ببر و از حضور و از هر چیزی و هر کسی که مرا به اینجا آورده بود تشکر کردم."),
        StoryParagraph("And Richard Parker, in that moment, did what I had never expected; he jumped out of the lifeboat, he ran across the sand, he disappeared into the jungle without looking back; and I called after him, called his name, called him to stop; but he did not stop, did not look back, did not say goodbye; and I wept, wept as I had never wept before, wept not because I was afraid but because I was alone, truly alone, alone for the first time in seven months, alone on the edge of a new world.", "و ریچارد پارکر در آن لحظه کاری کرد که هرگز انتظارش را نداشتم؛ از قایق نجات بیرون پرید، روی ماسه دوید، بدون نگاه به عقب در جنگل ناپدید شد؛ و دنبالش صدا زدم، نامش را، صدایش زدم که متوقف شود؛ اما متوقف نشد، برنگشت، خداحافظی نکرد؛ و گریستم، همانطور که هرگز قبلاً گریه نکرده بودم، نه چون می‌ترسیدم بلکه چون تنهایم، به‌راستی تنها، برای نخستین بار در هفت ماه تنها، در لبه جهانی نو."),
        StoryParagraph("And I understood, in that moment, that the story of the tiger and the boy was over, that the chapter of our companionship had ended, that the strange love that had grown between us, the impossible love, the divine love, was now something I would have to carry alone, something I would have to remember alone, something I would have to honor alone.", "و در آن لحظه فهمیدم که داستان ببر و پسر تمام شده بود، که فصل همراهی‌مان پایان یافته بود، که عشق عجیبی که میانمان رشد کرده بود، عشق ناممکن، عشق الهی، حالا چیزی بود که باید تنها حملش می‌کردم، چیزی که باید تنها به یادش می‌آوردم، چیزی که باید تنها حرمتش می‌نهادم."),
        StoryParagraph("And yet, even in that loneliness, even in that grief, even in that loss, I knew, with a certainty that came from somewhere deeper than thought, that Richard Parker was not really gone; that he lived on in me, that he would always live on in me, that the tiger and the boy were not two beings but one, had always been one, would always be one, in this world and in every world to come.", "و با این حال، حتی در آن تنهایی، حتی در آن اندوه، حتی در آن فقدان، می‌دانستم، با یقینی که از جایی عمیق‌تر از اندیشه می‌آمد، که ریچارد پارکر واقعاً نرفته بود؛ که در من زندگی می‌کرد، که همیشه در من زندگی می‌کرد، که ببر و پسر دو موجود نبودند بلکه یکی بودند، همیشه یکی بوده بودند، همیشه یکی می‌بودند، در این جهان و در هر جهان که بیاید."),
        StoryParagraph("And so the story continues, into the next chapter, into the last chapter, into the chapter where I tell you what happened after, where I tell you how I learned to live with what I had experienced, where I tell you how I learned to be human again.", "و اینگونه داستان ادامه می‌یابد، به فصل بعد، به فصل آخر، به فصلی که در آن برایتان می‌گویم چه اتفاقی افتاد، چگونه آموختم با آنچه تجربه کرده بودم زندگی کنم، چگونه آموختم دوباره انسان باشم."),
    )
)
    // ─────────── فصل ۶: نجات در مکزیک ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "Rescue in Mexico", titlePersian = "نجات در مکزیک",
        paragraphs = listOf(
            StoryParagraph("I was found by two men, Mexican fishermen, on the beach where I had collapsed, and I do not remember much of what happened in those first hours, because I was barely conscious, because my body had given up, because my mind had retreated to some deep, safe place from which it was watching the world through a long, dark tunnel.", "دو مرد مرا یافتند، دو ماهیگیر مکزیکی، روی ساحلی که در آن افتاده بودم و از آن ساعات نخست چیز زیادی به یاد نمی‌آورم، چون به‌سختی هشیار بودم، چون بدنم تسلیم شده بود، چون ذهنم به جایی عمیق و امن عقب نشسته بود که از آنجا جهان را از تونلی طولانی و تاریک تماشا می‌کرد."),
            StoryParagraph("They lifted me onto their boat, they wrapped me in blankets, they gave me water; I remember the taste of that water, remember it as the sweetest thing I have ever tasted, sweeter than the water on the island, sweeter than any water in the world, because it was the water of rescue, the water of return, the water of life."),
            StoryParagraph("They spoke to me in Spanish, and I did not understand, and they spoke to me in English, and I understood some, and they asked me questions, and I could not answer, and they looked at me with a mixture of pity and wonder, as if I were a creature they had never seen before, as if I were something that had crawled out of the depths of the sea.", "به اسپانیایی با من صحبت کردند و نفهمیدم و به انگلیسی صحبت کردند و کمی فهمیدم و پرسش‌هایی پرسیدند و نتوانستم پاسخ دهم و با آمیزه‌ای از ترحم و شگفتی نگاهم کردند، گویی موجودی بودم که هرگز ندیده بودند، گویی چیزی بودم که از اعماق دریا خزیده بود."),
            StoryParagraph("They took me to a hospital, to a small hospital in a small Mexican town, and the doctors examined me, and they could not believe what they saw; my body was skeletal, my skin was burned and peeling, my eyes were sunken and hollow, my hair was matted and gray; and yet, I was alive, inexplicably, impossibly, miraculously alive."),
            StoryParagraph("They asked me how long I had been at sea, and I told them, and they did not believe me; they asked me what I had eaten, and I told them, and they did not believe me; they asked me what had happened to the others, to the crew, to my family, and I told them, and they did not believe me.", "پرسیدند چند وقت در دریا بودم و گفتم و باور نکردند؛ پرسیدند چه خورده بودم و گفتم و باور نکردند؛ پرسیدند چه بر سر دیگران آمده، خدمه، خانواده‌ام و گفتم و باور نکردند."),
            StoryParagraph("And so I stopped telling them, stopped speaking, stopped explaining; I simply lay in my bed, in the small hospital, and I stared at the ceiling, and I waited for my body to heal, and I waited for my mind to return, and I waited for the world to make sense again."),
            StoryParagraph("The Japanese investigators came, weeks later, two men from the shipping company, two men who had come to find out what had happened to the Tsimtsum, two men who did not expect to find a survivor, who did not expect to find anyone alive.", "بازرسان ژاپنی هفته‌ها بعد آمدند، دو مرد از شرکت کشتیرانی، دو مردی که آمده بودند بفهمند بر سر سیم‌تسوم چه آمده، دو مردی که انتظار یافتن بازمانده‌ای نداشتند، انتظار یافتن کسی زنده را نداشتند."),
            StoryParagraph("They interviewed me, in my hospital room, in my bed, and they asked me the same questions that everyone had asked me, and I gave them the same answers that everyone had rejected; and they, too, did not believe me, and they, too, thought I was lying or mad, and they, too, would not accept the truth."),
            StoryParagraph("'A tiger?' one of them said, and he laughed, and he looked at his colleague, and his colleague laughed too, and I understood, in that moment, that they would never believe me, that no one would ever believe me, that my story was too strange, too impossible, too wonderful for the world to accept."),
            StoryParagraph("And so I told them a different story, a second story, a story without animals, a story without tigers, a story that the world could accept; and in that second story, I replaced Richard Parker with a man, a cook, a brutal, terrible man; and I replaced the orangutan with my mother; and I replaced the zebra with a sailor; and I kept myself as myself, a boy, a survivor, a witness to the worst that humans can do.", "و بنابراین داستان دیگری برایشان گفتم، داستان دومی، داستانی بدون حیوانات، بدون ببرها، داستانی که جهان می‌توانست بپذیرد؛ و در آن داستان دوم، ریچارد پارکر را با مردی جایگزین کردم، یک آشپز، مردی وحشی و هولناک؛ و اورانگوتان را با مادرم جایگزین کردم؛ و گورخر را با یک ملوان؛ و خودم را همان خودم نگه داشتم، پسری، بازمانده‌ای، شاهدی بر بدترین چیزی که انسان‌ها می‌توانند بکنند."),
            StoryParagraph("And they believed the second story, because it was a story they could understand, a story they had heard before, a story that fit the world they knew; and they wrote their report, and they went back to Japan, and the world moved on, and I was left alone with the truth, the truth that no one wanted to hear, the truth that no one could accept."),
            StoryParagraph("But the truth was not the second story, not the story of the cook and the sailor and the mother; the truth was the first story, the story of the tiger, the story of Richard Parker, the story that I had lived and that no one would ever believe; and I have carried that truth with me, all these years, in silence, in solitude, in the strange knowledge that the world's disbelief does not change what happened, does not change what I saw, does not change what I am.", "اما حقیقت داستان دوم نبود، نه داستان آشپز و ملوان و مادر؛ حقیقت داستان اول بود، داستان ببر، داستان ریچارد پارکر، داستانی که زندگی کرده بودم و هیچ‌کس هرگز باورش نمی‌کرد؛ و این حقیقت را تمام این سال‌ها با خود حمل کرده‌ام، در سکوت، در تنهایی، در دانش عجیب اینکه بی‌باور بودن جهان آنچه اتفاق افتاده را تغییر نمی‌دهد، آنچه دیده‌ام را، آنچه هستم را."),
            StoryParagraph("The hospital released me after several weeks, and I was taken in by a family, a Mexican family, kind people, generous people, people who did not know what to do with me but who tried, anyway, to give me a home; and I lived with them for a few months, and I healed, slowly, and I learned to speak again, to eat again, to sleep again."),
            StoryParagraph("The Canadian embassy arranged for my passage to Canada, and I crossed the border, and I arrived in Toronto, in a cold city, in a strange country, in a life that was not the one I had imagined; and I began, slowly, the long process of becoming human again, of becoming a person with a future, of becoming someone who was not defined by his past.", "سفارت کانادا گذر مرا به کانادا ترتیب داد و از مرز گذشتم و به تورنتو رسیدم، به شهری سرد، به کشوری غریب، به زندگی‌ای که آن نبود که تصور کرده بودم؛ و آهسته، فرایند طولانی دوباره انسان شدن را آغاز کردم، شدن شخصی با آینده، شدن کسی که گذشته‌اش تعریفش نمی‌کرد."),
            StoryParagraph("I went to school, and I studied, and I learned; I went to university, and I graduated, and I became a biologist; I studied the animals that I had once lived with, the tigers and the orangutans and the zebras, and I learned about them in a way that I had never learned before, in a way that was scientific, objective, detached.", "به مدرسه رفتم و درس خواندم و آموختم؛ به دانشگاه رفتم و فارغ‌التحصیل شدم و زیست‌شناس شدم؛ حیواناتی را که زمانی با آن‌ها زندگی کرده بودم مطالعه کردم، ببرها و اورانگوتان‌ها و گورخرها و درباره‌شان به شیوه‌ای آموختم که هرگز قبلاً نیاموخته بودم، به شیوه‌ای علمی، عینی، جدا."),
            StoryParagraph("But even as I studied them, even as I learned about their behavior and their instincts and their evolution, I could not forget what I had experienced with Richard Parker; I could not forget the look in his eyes, the sound of his breathing, the warmth of his presence; and I could not forget that, in some strange way, he had saved my life, not by protecting me but by forcing me to stay alert, to stay alive, to stay human."),
            StoryParagraph("I married a woman, a Canadian woman, a woman named Meena, and we had a son, and we had a daughter, and we built a life together, a quiet life, a good life, a life that was everything I had once thought I had lost forever; and yet, even in that life, even in that happiness, even in that peace, I could not escape the ocean, could not escape the tiger, could not escape the truth.", "با زنی ازدواج کردم، زنی کانادایی، زنی به نام مینا و پسری داشتیم و دختری و با هم زندگی‌ای ساختیم، زندگی‌ای آرام، زندگی‌ای خوب، زندگی‌ای که هر چیزی بود که روزی فکر می‌کردم برای همیشه از دست داده‌ام؛ و با این حال، حتی در آن زندگی، حتی در آن خوشبختی، حتی در آن آرامش، نمی‌توانستم از اقیانوس بگریزم، از ببر، از حقیقت."),
            StoryParagraph("I told my story, once, to a writer, a man who had come to interview me for a magazine; I told him everything, the whole story, the true story, the story of the tiger; and he listened, and he wrote it down, and he published it, and the world, this time, believed; and I became, in a small way, famous, a curiosity, a man who had survived the impossible."),
            StoryParagraph("But fame, I have learned, is not the same as being understood; and belief, I have learned, is not the same as understanding; the world believed my story, but the world did not understand it, and the world could not understand it, because the world had never been where I had been, had never seen what I had seen, had never known what I had known."),
            StoryParagraph("And so I continue to tell the story, not because I want to be believed, not because I want to be understood, but because the story demands to be told, because the story will not let me rest, because the story is the truth and the truth must be spoken, even if no one is listening, even if no one cares, even if no one believes.", "و بنابراین به تعریف داستان ادامه می‌دهم، نه چون می‌خواهم باور شوم، نه چون می‌خواهم فهمیده شوم، بلکه چون داستان می‌خواهد گفته شود، چون داستان نمی‌گذارد بیاسایم، چون داستان حقیقت است و حقیقت باید گفته شود، حتی اگر هیچ‌کس گوش ندهد، حتی اگر هیچ‌کس اهمیت ندهد، حتی اگر هیچ‌کس باور نکند."),
            StoryParagraph("I have, over the years, come to understand something about stories, something that I did not understand when I was young; I have come to understand that stories are not merely entertainment, not merely ways to pass the time, not merely accounts of what happened; stories are ways of knowing, ways of understanding, ways of being; and the stories we tell, and the stories we believe, shape who we are and who we become."),
            StoryParagraph("I have come to understand, also, that there are always two stories, at least two, for every event; the story that happened and the story that we tell; and the story we tell is not always the same as the story that happened, because the story we tell is filtered through our minds, shaped by our beliefs, colored by our emotions, distorted by our needs.", "همچنین فهمیده‌ام که همیشه دو داستان هست، حداقل دو، برای هر واقعه؛ داستانی که اتفاق افتاد و داستانی که تعریف می‌کنیم؛ و داستانی که تعریف می‌کنیم همیشه همان داستانی که اتفاق افتاده نیست، چون داستانی که تعریف می‌کنیم از ذهنمان می‌گذرد، توسط باورهایمان شکل می‌گیرد، توسط احساساتمان رنگ می‌گیرد، توسط نیازهایمان تحریف می‌شود."),
            StoryParagraph("And the question, the deepest question, the question that the two Japanese investigators asked me, all those years ago, and that I could not answer then and can barely answer now, is this: which story is true? Which story is the real story? The story with the tiger, or the story without?"),
            StoryParagraph("And the answer, I have come to believe, is that both stories are true; both stories are real; both stories are the same story, told in different languages, understood in different ways, remembered in different forms; and that the truth, the deepest truth, is not in the story itself but in the meaning we find in it, the meaning we make of it, the meaning we live by."),
            StoryParagraph("I have lived my life by the story of the tiger, because the story of the tiger is the story of my soul; and yet, I have also lived my life by the story of the humans, because the story of the humans is the story of my body, my history, my name; and I have learned, at last, that these two stories are not opposed, not competing, not contradictory; they are two sides of the same reality, two faces of the same truth, two languages for the same prayer.", "عمرم را بر اساس داستان ببر زندگی کرده‌ام، چون داستان ببر داستان روح من است؛ و با این حال، عمرم را بر اساس داستان انسان‌ها هم زندگی کرده‌ام، چون داستان انسان‌ها داستان بدن من است، تاریخ من، نام من؛ و سرانجام آموخته‌ام این دو داستان متضاد نیستند، رقیب، متناقض؛ دو روی همان واقعیت‌اند، دو چهره همان حقیقت، دو زبان برای همان دعا."),
            StoryParagraph("The world wanted the story without the tiger, because the world could not believe in the tiger; and I gave the world what it wanted, but I kept the tiger for myself; and in that keeping, in that secret, in that private faith, I preserved something that the world could not take from me, something that the world could not touch, something that was mine alone."),
            StoryParagraph("For the tiger was not merely a tiger; the tiger was a symbol, a sign, a messenger; the tiger was the wildness within me, the fear within me, the hunger within me, the life within me; the tiger was everything that civilization tries to tame, everything that society tries to hide, everything that religion tries to redeem; and yet, the tiger was also grace, also love, also god."),
            StoryParagraph("I have spent my whole life trying to understand Richard Parker, trying to understand what he meant, trying to understand what he was; and I have come to believe that he was not merely an animal, not merely a tiger, not merely a creature of instinct and appetite; he was, in some way that I can never fully explain, the presence that I had felt on the ocean, the divine that I had encountered in the night, the mystery that I had touched in the darkness.", "تمام عمرم را صرف تلاش برای فهمیدن ریچارد پارکر کرده‌ام، تلاش برای فهمیدن معنایش، چیستی‌اش؛ و به باور رسیده‌ام که او تنها حیوانی نبود، تنها ببری، تنها موجودی از غریزه و اشتها؛ او، به شیوه‌ای که هرگز کاملاً نمی‌توانم توضیح دهم، همان حضوری بود که روی اقیانوس حس کرده بودم، همان الهی که در شب با آن روبرو شده بودم، همان رازی که در تاریکی لمس کرده بودم."),
            StoryParagraph("And so Richard Parker is not dead, not really; Richard Parker lives on, in me, in my memory, in my heart, in my dreams, in every breath I take, in every word I speak, in every thought I think; Richard Parker is the tiger that walks beside me, always, the tiger that I will never, ever, let go."),
            StoryParagraph("And so the story of the tiger and the boy continues, past the hospital, past the interviews, past the marriage and the children and the quiet life in Toronto; the story continues into this moment, into this telling, into this act of confession and witness and love; and I know, at last, that the story will continue forever, because the story is not mine, not really, not entirely; the story belongs to everyone who has ever suffered, everyone who has ever survived, everyone who has ever loved."),
            StoryParagraph("And so I end my telling, not with a conclusion, but with a beginning; not with an answer, but with a question; not with a resolution, but with a gift; the gift of the story, the gift of the tiger, the gift of the truth."),
            StoryParagraph("And the question I leave with you, the question that the story has asked me all my life, the question that I now ask you, is this: which story do you prefer? The story with the tiger, or the story without? And, more importantly, which story is true? And, most importantly of all, does the answer even matter?"),
            StoryParagraph("For in the end, I have come to believe, it is not the answer that matters but the asking; not the truth that matters but the seeking; not the certainty that matters but the faith; and that the greatest faith of all, the deepest faith, the truest faith, is the faith that trusts, even in the absence of proof, even in the face of doubt, even in the presence of despair."),
            StoryParagraph("And so I thank you, for listening, for holding my story, for being a witness to a truth that no one else may ever believe; and I thank the ocean, for teaching me, for testing me, for carrying me; and I thank Richard Parker, most of all, for being with me, for being my companion, for being the presence of the divine in the middle of the greatest darkness of my life.", "و بنابراین از شما سپاسگزارم، برای شنیدن، برای حمل داستانم، برای شاهدی بودن بر حقیقتی که ممکن است هیچ‌کس دیگری هرگز باور نکند؛ و از اقیانوس سپاسگزارم، برای آموزش دادن، برای آزمودن، برای حمل کردن؛ و از ریچارد پارکر، بیش از همه، برای با من بودن، برای همسفر بودن، برای حضور الهی بودن در میانه بزرگ‌ترین تاریکی زندگی‌ام."),
            StoryParagraph("And so the story ends, in a hospital room in Mexico, in an apartment in Toronto, in a heart that has been broken and healed and broken and healed again; and yet, in a deeper sense, the story does not end, cannot end, will not end, because the story is not a thing that can be finished, but a thing that must be lived, moment by moment, breath by breath, day by day."),
            StoryParagraph("For the tiger is always with us, and the ocean is always within us, and the presence is always around us; and the story of the tiger and the boy is the story of each one of us, the story of our own journey through the darkness, the story of our own encounter with the divine, the story of our own survival and transformation and return.", "زیرا ببر همیشه با ماست و اقیانوس همیشه درون ما و حضور همیشه اطراف ما؛ و داستان ببر و پسر داستان هر یک از ماست، داستان سفر خودمان در تاریکی، داستان رویارویی خودمان با الهی، داستان بقا و دگرگونی و بازگشت خودمان."),
            StoryParagraph("And so I end, and so I begin, and so the story continues, into the last chapter, into the final revelation, into the truth that lies beyond all stories."),
        )
    )

    // ─────────── فصل ۷: معنا ───────────
    private fun chapter7() = StoryChapter(
        number = 7, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Life of Pi, published in 2001, is not merely a novel; it is a meditation, a confession, a prayer; it is a story about survival and a story about faith, a story about the ocean and a story about the soul, a story about a boy and a tiger and the God who is present in both.", "زندگی پی، منتشرشده در ۲۰۰۱، تنها رمان نیست؛ مراقبه‌ای است، اعترافی، دعایی؛ داستانی است درباره بقا و داستانی درباره ایمان، داستانی درباره اقیانوس و داستانی درباره روح، داستانی درباره پسری و ببری و خدایی که در هر دو حاضر است."),
            StoryParagraph("It is, on the surface, a novel about a shipwreck, about a boy stranded on a lifeboat, about a tiger and a raft and a seven-month journey across the Pacific Ocean; but at a deeper level, it is a novel about what it means to be human, about what it means to believe, about what it means to love."),
            StoryParagraph("The two stories, the story with the tiger and the story without, are the heart of the novel; and the question of which story is true, and which story we prefer, is the question that Yann Martel is asking us, the question that he wants us to answer for ourselves."),
            StoryParagraph("For the story with the tiger is the story of faith; it is the story of a reality that is larger than our reason, deeper than our logic, more wonderful than our imagination; it is the story of a world in which God is present, in which miracles happen, in which love is not merely a human emotion but a divine force.", "زیرا داستان با ببر داستان ایمان است؛ داستان واقعیتی بزرگ‌تر از عقل، عمیق‌تر از منطق، شگفت‌انگیزتر از تخیل؛ داستانی از جهانی که در آن خدا حاضر است، که در آن معجزات اتفاق می‌افتند، که در آن عشق تنها یک احساس انسانی نیست بلکه نیرویی الهی است."),
            StoryParagraph("And the story without the tiger is the story of reason; it is the story of a reality that can be explained, that can be understood, that can be contained within the boundaries of the human mind; it is the story of a world in which God is absent, in which miracles do not happen, in which love is merely chemistry, merely biology, merely a survival mechanism."),
            StoryParagraph("Both stories are true, in their own way; both stories are real, in their own sense; and yet, Martel suggests, the story with the tiger is the better story, the more beautiful story, the story that we should choose, because the story with the tiger is the story that gives life meaning."),
            StoryParagraph("Pi tells both stories to the investigators, and he asks them which they prefer; they prefer the story with the tiger, because it is the better story; and Pi says, 'Thank you. And so it goes with God.'"),
            StoryParagraph("And this, at last, is the meaning of the novel: that the question of God is not a question of fact, not a question of proof, not a question of certainty; it is a question of preference, of choice, of faith; and the answer we give is not about what is true but about who we are.", "و این، سرانجام، معنای رمان است: که پرسش خدا پرسش واقعیت نیست، پرسش اثبات نیست، پرسش یقین نیست؛ پرسشی است درباره ترجیح، درباره انتخاب، درباره ایمان؛ و پاسخی که می‌دهیم درباره آنچه درست است نیست بلکه درباره کیستی ماست."),
            StoryParagraph("Those who prefer the story with the tiger are those who can believe, those who can hope, those who can love; those who prefer the story without are those who cannot, those who need certainty, those who are afraid of mystery."),
            StoryParagraph("And Martel, I believe, is not judging either group; he is not saying that believers are better than non-believers, or vice versa; he is simply observing that we all choose our stories, that we all choose our faiths, that we all choose our lives; and that the choice is ours, always ours, and that this is what freedom is."),
            StoryParagraph("The novel is about faith, but it is also about doubt; it is about belief, but it is also about uncertainty; it is about God, but it is also about the absence of God; because Martel understands, as all great writers understand, that faith is not the absence of doubt but the presence of it, that belief is not the absence of uncertainty but the acceptance of it, that God is not the absence of mystery but the embrace of it.", "رمان درباره ایمان است اما درباره شک هم است؛ درباره باور است اما درباره عدم قطعیت؛ درباره خداست اما درباره غیاب خدا؛ چون مارتل می‌فهمد، همانطور که همه نویسندگان بزرگ می‌فهمند، که ایمان نبود شک نیست بلکه حضورش است، که باور نبود عدم قطعیت نیست بلکه پذیرشش، که خدا نبود راز نیست بلکه در آغوش گرفتنش."),
            StoryParagraph("The novel is about the ocean, and the ocean is a symbol for life itself; the ocean is vast, and the ocean is dangerous, and the ocean is beautiful; the ocean is indifferent, and the ocean is alive; and we are all, all of us, sailors on the ocean of existence, drifting on rafts of our own making, seeking something that we cannot name, hoping for something that we cannot see."),
            StoryParagraph("The novel is about the tiger, and the tiger is a symbol for everything that is wild and dangerous and alive within us; the tiger is our fear, and the tiger is our hunger, and the tiger is our will to survive; the tiger is what civilization tries to tame, and the tiger is what we must, at last, befriend."),
            StoryParagraph("And the novel is about the boy, and the boy is all of us; the boy is our innocence, and the boy is our vulnerability, and the boy is our hope; the boy is who we were before the world broke us, and the boy is who we must become again, if we are to be saved."),
            StoryParagraph("Yann Martel wrote this novel after his own journey through the darkness; he had spent years trying to write, and he had failed, and he had almost given up; and then, one day, he read a review of a book about a man who had survived a shipwreck, and something in that review, something in that story, caught his imagination, and he began to write.", "یان مارتل این رمان را پس از سفر خودش در تاریکی نوشت؛ سال‌ها تلاش کرده بود بنویسد و شکست خورده بود و تقریباً تسلیم شده بود؛ و سپس، یک روز، نقدی از کتابی درباره مردی که از کشتی‌شکستگی جان به‌در برده بود خواند و چیزی در آن نقد، چیزی در آن داستان، تخیلش را گرفت و شروع کرد به نوشتن."),
            StoryParagraph("And in the writing, in the years of writing, Martel found something; he found a story that was larger than himself, a story that asked the questions he had been afraid to ask, a story that answered the questions he had been afraid to answer; and he gave that story to the world, and the world, in return, gave him the Booker Prize."),
            StoryParagraph("But prizes, Martel has said, do not matter; what matters is the story; what matters is the truth that the story contains; what matters is the effect that the story has on those who read it, and on those who live it, and on those who are transformed by it."),
            StoryParagraph("And that is what this novel does: it transforms; it does not merely entertain, does not merely inform, does not merely instruct; it transforms; it takes the reader on a journey, an inner journey, a journey into the depths of the soul; and it brings the reader back, changed, different, more alive.", "و این همان کاری است که این رمان می‌کند: دگرگون می‌کند؛ تنها سرگرم نمی‌کند، تنها اطلاع نمی‌دهد، تنها آموزش نمی‌دهد؛ دگرگون می‌کند؛ خواننده را به سفری می‌برد، سفری درونی، سفری به اعماق روح؛ و خواننده را بازمی‌گرداند، تغییر‌یافته، متفاوت، زنده‌تر."),
            StoryParagraph("For the novel is not really about a tiger, not really about a boy, not really about a shipwreck; it is about you, the reader; it is about your life, your journey, your suffering, your survival; it is about the tiger within you, and the ocean within you, and the God within you.", "زیرا رمان واقعاً درباره ببری نیست، درباره پسری، درباره کشتی‌شکستگی؛ درباره توست، خواننده؛ درباره زندگی تو، سفر تو، رنج تو، بقای تو؛ درباره ببر درون تو و اقیانوس درون تو و خدای درون تو."),
            StoryParagraph("And the question the novel asks is not merely a literary question, not merely a philosophical question, not merely a theological question; it is a personal question, a question that each of us must answer for ourselves: which story do you prefer? Which story is your story? Which story do you choose to live by?"),
            StoryParagraph("For we are all, in the end, storytellers; we all create our own realities, our own truths, our own gods; we all choose the stories that we will live by, the stories that will shape us, the stories that will save us; and the stories we choose, the stories we tell, the stories we believe, become the stories we are."),
            StoryParagraph("And so I end where I began, in Toronto, in the small house, with the man named Pi Patel, who has lived a story that no one believes, and who has kept a tiger in his heart for thirty years; and I end with the hope that you, the reader, will believe, will keep the tiger too, will find the presence that Pi found, on the ocean, in the darkness, in the divine.", "و اینگونه همان‌جا پایان می‌دهم که آغاز کردم، در تورنتو، در خانه کوچک، با مردی به نام پای پاتل، که داستانی زندگی کرده که هیچ‌کس باور نمی‌کند و ببری را سی سال در قلبش نگه داشته؛ و با این امید پایان می‌دهم که تو، خواننده، باور کنی، تو هم ببر را نگه داری، حضوری که پای یافت را بیابی، روی اقیانوس، در تاریکی، در الهی."),
            StoryParagraph("For the presence is not far away; the presence is here, now, always; the presence is in the sunrise and the sunset, in the ocean and the sky, in the tiger and the boy, in you and in me; the presence is the love that binds us all, the life that sustains us all, the hope that saves us all."),
            StoryParagraph("And so the story of Pi Patel, the story of the tiger and the boy, the story of the ocean and the soul, comes to its end, and yet does not end, because stories, like lives, are not things that can be finished; they are things that must be lived, moment by moment, breath by breath, day by day, for all the days of our lives."),
            StoryParagraph("And so I thank you, for reading, for journeying with me, for being a witness to a story that has haunted me for all these years; and I ask you, one last time, to remember the question, to hold the question, to live the question: which story do you prefer?"),
            StoryParagraph("And so ended the story of Pi Patel, the boy who survived, the boy who sailed with a tiger, the boy who learned, in the middle of the Pacific Ocean, what it means to be alive.", "و اینگونه داستان پای پاتل پایان یافت، پسری که زنده ماند، پسری که با ببری سفر کرد، پسری که در میانه اقیانوس آرام یاد گرفت زنده بودن یعنی چه."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the story, I hope, goes on — in you, the reader, who now hold it; in the tiger, who lives on in your heart; in the presence, who waits for you, always, in every ocean, in every night, in every story."),
            StoryParagraph("For the tiger is always there, and the ocean is always within, and the presence is always with us, and the story, the great story, the only story, goes on, forever and ever, world without end."),
            StoryParagraph("Amen.", "آمین."),
        )
    )
}